    "allwain no integra publicidad ni vende datos personales. Cada acción importante necesita confirmación y cada operación conserva un rastro comprensible.": "allwain does not include advertising or sell personal data. Every important action requires confirmation, and every transaction keeps a clear trail.",
    "allwain no vende datos personales ni integra seguimiento publicitario. Esta Guía no entra en tu cuenta. La conexión usa HTTPS y las sesiones son revocables: son controles reales y evolutivos, no una promesa de invulnerabilidad.": "allwain does not sell personal data or use advertising tracking. This Guide does not access your account. The connection uses HTTPS and sessions can be revoked: these are real, evolving controls, not a promise of invulnerability.",
    "allwain solo mostrará este distintivo cuando la documentación del lote haya sido comprobada.": "allwain will display this label only after the batch documentation has been checked.",
