    "allwain tiene tres papeles: Comprador, que publica lo que necesita y elige; Vendedor, que responde con propuestas; y Conector, que acerca personas y negocios mediante su QR sin entrar en sus cuentas. Repartir es una función distinta y voluntaria.": "allwain has three roles: Buyer, who publishes what they need and chooses; Seller, who responds with proposals; and Connector, who brings people and businesses together through their QR without accessing their accounts. Delivery is a separate, optional function.",
    "allwain usa HTTPS, cabeceras de seguridad y sesiones revocables. Son controles reales y evolutivos, no una promesa de invulnerabilidad.": "allwain uses HTTPS, security headers and revocable sessions. These are real, evolving safeguards, not a promise of invulnerability.",
