    "DESCUBRE PETICIONES": "DISCOVER REQUESTS",
    "Descubres clientes y peticiones, no un catálogo de productos. Respondes a los grupos que encajan con tu negocio y puedes ajustar una oferta más competitiva al volumen real.": "You discover customers and requests, not a product catalogue. You respond to groups that fit your business and can tailor a more competitive offer to the actual volume.",
