    "EJEMPLO": "EXAMPLE",
    "Ejemplo de comarca: más alcance exige más soporte y reglas claras; no implica ingresos garantizados.": "District network example: wider reach requires more support and clear rules; it does not imply guaranteed income.",
    "Ejemplo de red de pueblo: se atribuye quién llegó contigo y qué operaciones completa, nunca simples altas.": "Town network example: it records who joined through you and which transactions they complete, never sign-ups alone.",
    "Ejemplo de red inicial: el beneficio solo se compartiría cuando existan operaciones válidas y terminadas.": "Initial network example: the benefit would be shared only when valid transactions have been completed.",
    "Ejemplo visual: precios y respuestas no reales. Tú decides si publicas y cuál eliges.": "Visual example: prices and responses are not real. You decide whether to publish and which one to choose.",
    "El Conector acerca compradores y negocios a su red local": "The Connector brings buyers and businesses into their local network",
    "El Conector comparte su QR, acerca compradores y negocios y activa allwain en su zona. La red que incorpora queda vinculada a él; recomendar no le da acceso a cuentas ni decisiones.": "The Connector shares their QR, brings buyers and businesses closer and activates allwain in their area. The network they bring in remains linked to them; recommending does not grant access to accounts or decisions.",
    "El Conector comparte su QR, acerca compradores y negocios y activa la red de allwain en su zona. La red que incorpora queda vinculada a él; recomendar no le da acceso a cuentas ni decisiones.": "The Connector shares their QR, brings buyers and businesses together and activates the allwain network in their area. The network they bring in remains linked to them; recommending does not grant access to accounts or decisions.",
    "El distintivo de allwain solo se mostrará cuando la documentación del lote haya sido comprobada.": "The allwain label will be displayed only after the batch documentation has been checked.",
    "El envío es automático y queda vinculado a tu cuenta.": "Submission is automatic and linked to your account.",
    "El laboratorio de allwain empieza aquí: un único producto, naranjas Navel Lane Late, y personas invitadas a probar, señalar fallos y opinar antes de la preventa.": "The allwain lab starts here: one product, Navel Lane Late oranges, and people invited to test, report problems and share their views before the presale.",
    "EL MERCADO AL REVÉS": "THE MARKET REVERSED",
    "El modelo prevé que el Conector participe en cada compra o venta válida y terminada de su red. No cobra por altas. Los pagos, porcentajes y reglas se publicarán antes de activarse.": "The model envisages the Connector participating in each valid, completed purchase or sale in their network. They are not paid for sign-ups. Payments, percentages and rules will be published before activation.",
    "El modelo que queremos poner a prueba": "The model we want to test",
    "El objetivo de más de 300 % se comprobará frente a la referencia de origen que quede documentada en la prueba. El 50 % toma como referencia aportada 2 €/kg frente al objetivo de 1 €/kg para el producto. No son resultados confirmados. Entrega, comisiones, impuestos, embalaje, mermas y ajustes irán aparte y serán visibles.": "The target of more than 300% will be tested against the documented farm-gate reference used in the trial. The 50% target uses the supplied reference of €2/kg compared with the product target of €1/kg. These are not confirmed results. Delivery, fees, taxes, packaging, losses and adjustments will be separate and visible.",
    "El primer QR y la hora confirman que el producto ha salido del punto acordado.": "The first QR and timestamp confirm that the product has left the agreed collection point.",
    "El progreso se guarda en tu cuenta de allwain.": "Your progress is saved to your allwain account.",
    "EL QR YA SE PUEDE COMPARTIR · LOS PAGOS AÚN NO": "THE QR CAN ALREADY BE SHARED · PAYMENTS ARE NOT ACTIVE YET",
    "El recorrido que puede evitarse cuando ya existe producto local": "The journey that can be avoided when the product is already available locally",
    "el reparto remunerado se probará cuando estén cerradas sus condiciones, seguro y obligaciones fiscales.": "paid delivery will be tested once its terms, insurance and tax obligations have been finalised.",
    "El segundo QR confirma la recepción y permite cerrar la operación con un rastro comprensible.": "The second QR confirms receipt and allows the transaction to close with a clear trail.",
    "El vendedor encuentra peticiones reales en vez de esperar solo ante un catálogo y decide a cuáles responder con una propuesta competitiva. Gana una oportunidad de venta, no una venta garantizada: el comprador compara y elige. En la prueba de naranjas, más de 300 % para quien cultiva es un objetivo por comprobar, no un resultado confirmado.": "The seller finds real requests instead of waiting behind a catalogue and decides which ones to answer with a competitive proposal. This is a sales opportunity, not a guaranteed sale: the buyer compares and chooses. In the orange trial, more than 300% for the grower is a target to be tested, not a confirmed result.",
    "El vendedor entra.": "The seller walks in.",
    "El vendedor podrá elegir una petición y responder con una oferta o una negociación": "The seller will be able to choose a request and respond with an offer or a negotiation",
    "El vendedor ve peticiones compatibles, elige cuáles le interesan y responde con una oferta o una negociación. El comprador conserva la decisión.": "The seller sees compatible requests, chooses which ones interest them and responds with an offer or a negotiation. The buyer retains the final decision.",
    "El visor convierte la etiqueta en una petición editable. La revisas y, con un toque, preguntas a una gran comunidad. Después comparas las respuestas.": "The viewer turns the label into an editable request. You review it and, with one tap, ask a large community. Then you compare the responses.",
