    "Email o contraseña incorrectos.": "Incorrect email or password.",
    "Empezar la encuesta": "Start the survey",
    "Empiezo": "Starting out",
    "En esta Guía se procesa el texto que escribes y un historial breve para entender preguntas de seguimiento. No entra en tu cuenta ni consulta pedidos, pagos o mensajes privados; allwain no vende datos personales.": "This Guide processes the text you enter and a short conversation history to understand follow-up questions. It does not access your account or view orders, payments or private messages; allwain does not sell personal data.",
    "En este centro comercial no descubre productos: descubre peticiones y grupos de demanda. Elige cuáles puede atender y responde con una oferta más competitiva.": "In this shopping centre, sellers do not discover products: they discover requests and demand groups. They choose which ones they can serve and respond with a more competitive offer.",
    "ENCUESTA PENDIENTE": "SURVEY PENDING",
    "ENCUESTA PIONEROS WEB": "WEB PIONEER SURVEY",
    "Encuesta rápida": "Quick survey",
    "ENCUESTA RÁPIDA · MENOS DE 1 MINUTO": "QUICK SURVEY · UNDER 1 MINUTE",
    "English": "English",
    "ENTRA": "ENTERS",
    "Entra con la misma cuenta que usarás en la app. Tendrás una guía de acciones, progreso e incidencias sin abrir el correo.": "Sign in with the same account you will use in the app. You will have an action guide, progress tracking and issue reporting without opening your email app.",
    "Entra con tu cuenta de allwain para guardar el recorrido y enviar incidencias.": "Sign in with your allwain account to save your journey and submit issues.",
    "Entra con tu cuenta, vuelve al inicio y comprueba que entiendes cómo cambiar de espacio.": "Sign in with your account, return to Home and check that you understand how to switch spaces.",
