    "Escena fotográfica representativa de una persona compartiendo un QR con una comerciante y un vecino": "Representative photo of a person sharing a QR with a shopkeeper and a neighbour",
    "Escribe una pregunta…": "Type a question…",
    "Ese email ya tiene cuenta. Pulsa «Ya tengo cuenta».": "That email already has an account. Select ‘I already have an account’.",
    "Eso es sostenibilidad real.": "That is real sustainability.",
    "Español": "Español",
    "Esperando tu permiso. No guardaremos la ubicación.": "Waiting for your permission. We will not store your location.",
    "está agrupada.": "grouped.",
    "Estado de la sesión y configuración de la prueba": "Session status and test settings",
    "Estamos comprobando de forma segura si ya completaste la antesala.": "We are securely checking whether you have completed the initial survey.",
    "Estás interactuando con una IA. Tu pregunta y, cuando haga falta, una pregunta reciente de esta conversación pueden ser procesadas por OpenAI. No escribas nombres, direcciones, documentos, tarjetas ni datos de una operación.": "You are interacting with an AI. Your question and, when needed, one recent question from this conversation may be processed by OpenAI. Do not enter names, addresses, documents, card details or transaction data.",
    "Este espacio no evalúa las maquetas de la web. Te acompaña en acciones concretas dentro de la app y reúne tu progreso e incidencias en una sola cuenta.": "This space does not assess the website prototypes. It guides you through specific actions in the app and keeps your progress and issue reports together in one account.",
    "Este navegador no ofrece geolocalización. Mantenemos de Foios a Foios.": "This browser does not provide geolocation. We will keep ‘from Foios to Foios’.",
    "Estoy probando en": "I am testing on",
    "Explora cómo se comparte el beneficio.": "Explore how the benefit is shared.",
    "Explorar Conector": "Explore Connector",
    "FOIOS": "FOIOS",
    "Fotografías una etiqueta o explicas qué necesitas. allwain prepara un borrador para que lo revises; tú confirmas la petición, comparas respuestas y eliges.": "You photograph a label or explain what you need. allwain prepares a draft for you to review; you confirm the request, compare responses and choose.",
