    "Gracias. Tu opinión ya está registrada y vinculada a tu identidad allwain.": "Thank you. Your feedback has been recorded and linked to your allwain identity.",
    "Gracias. Tu opinión ya está registrada y vinculada a tu identidad de allwain.": "Thank you. Your feedback has been recorded and linked to your allwain identity.",
    "GRUPO ABIERTO": "OPEN GROUP",
