    "GUÍA IA PÚBLICA": "PUBLIC AI GUIDE",
    "Guía IA pública de allwain": "allwain public AI Guide",
    "Guía no disponible": "Guide unavailable",
    "Hay tres papeles en allwain: Comprador, que publica lo que necesita y elige; Vendedor, que responde con propuestas; y Conector, que acerca personas y negocios mediante su QR sin entrar en sus cuentas. Repartir es una función distinta y voluntaria.": "There are three roles in allwain: Buyer, who publishes what they need and chooses; Seller, who responds with proposals; and Connector, who brings people and businesses together through their QR without accessing their accounts. Delivery is a separate, optional function.",
    "Haz crecer la red": "Grow the network",
