    "Km 0": "Zero-mile",
    "KM 0": "ZERO-MILE",
    "La app queda bloqueada": "The app becomes unusable",
    "La contraseña debe tener al menos 12 caracteres.": "The password must be at least 12 characters long.",
    "La contraseña viaja cifrada y no se guarda en esta página.": "Your password is encrypted in transit and is not stored on this page.",
    "La demanda y el volumen deben encajar": "Demand and volume must align",
    "La demanda ya": "Demand is already",
    "La encuesta es la antesala de esta academia. Después de enviarla con tu cuenta, volverás aquí automáticamente.": "The survey is the first step into this testing academy. After submitting it with your account, you will return here automatically.",
    "La encuesta solo se registra vinculada a una identidad allwain. Al entrar, se enviará automáticamente sin abrir tu correo.": "The survey is recorded only when linked to an allwain identity. Once you sign in, it will be sent automatically without opening your email app.",
    "La encuesta y tu identidad abren esta sala.": "The survey and your identity unlock this room.",
    "La entrega cierra la ruta.": "Delivery completes the route.",
    "La entrega puede remunerar a alguien cercano.": "Delivery can provide income to someone nearby.",
    "La fiscalidad del Conector aún no está activada. Su participación se plantea solo sobre compras o ventas válidas y terminadas de su red, nunca por altas; porcentajes, impuestos, justificantes y liquidaciones se publicarán antes del primer pago.": "The Connector tax framework is not active yet. Their participation is planned only for valid, completed purchases or sales in their network, never for sign-ups; percentages, taxes, supporting documents and settlements will be published before the first payment.",
    "La incidencia llega automáticamente al panel de soporte y queda vinculada a tu cuenta. No se abre el correo.": "The issue report is sent automatically to the support dashboard and linked to your account. Your email app will not open.",
    "La misma identidad enlaza la encuesta, este recorrido y tus incidencias.": "The same identity links the survey, this journey and your issue reports.",
    "La persona que reparte ve distancia, importe y condiciones. Esta maqueta no inicia ninguna ruta.": "The person making the delivery sees the distance, payment and terms. This prototype does not start any route.",
    "La presentación funciona sin JavaScript. Para usar la Guía pública necesitas activarlo.": "The presentation works without JavaScript. You need to enable it to use the public Guide.",
    "LA PREVENTA AÚN NO HA EMPEZADO": "THE PRESALE HAS NOT STARTED YET",
    "La preventa aún no se ha abierto porque esta primera prueba debe cerrar condiciones de participación, entrega, trazabilidad y soporte. La web pública explica el modelo con maquetas libres; la prueba y sus incidencias se realizan en la app desde la sala privada. Cuando esos puntos estén verificados, se publicará una fecha.": "The presale is not open yet because this first trial still needs to finalise participation, delivery, traceability and support conditions. The public website explains the model with freely explorable prototypes; testing and issue reporting take place in the app from the private tester room. A date will be published once those points have been verified.",
    "La preventa es próxima, pero todavía no hay una fecha pública confirmada. Empezará con naranjas Navel Lane Late de Foios a 1 €/kg como precio objetivo; antes se publicarán las condiciones de entrega y participación.": "The presale is coming soon, but there is no confirmed public date yet. It will begin with Navel Lane Late oranges from Foios at a target price of €1/kg; delivery and participation terms will be published beforehand.",
    "La preventa y la primera operación siguen pendientes.": "The presale and first transaction are still pending.",
    "La primera prueba": "The first trial",
    "La prueba de las naranjas": "The orange trial",
    "La prueba empezará con un único producto: naranjas Navel Lane Late de Foios, de calidad, gran calibre y naranja intenso. Un euro por kilo es el objetivo del producto; la preventa y la primera venta siguen pendientes. Más de 300 % más para quien cultiva y 50 % menos para quien compra son objetivos comparados con las referencias aportadas, no resultados confirmados.": "The trial will begin with one product: quality Navel Lane Late oranges from Foios, large and deep orange in colour. One euro per kilogram is the product target; the presale and first sale are still pending. More than 300% more for growers and 50% less for buyers are targets compared with the supplied references, not confirmed results.",
    "La recogida deja una prueba verificable.": "Collection leaves verifiable evidence.",
    "La red de allwain crece": "The allwain network grows",
    "La ruta debe poder demostrarse de principio a fin, sin prometer resultados antes de probarla.": "The route must be demonstrable from start to finish, without promising results before it is tested.",
    "La ruta une dos puntos cercanos.": "The route connects two nearby points.",
    "La sesión ha caducado. Identifícate de nuevo para continuar.": "Your session has expired. Sign in again to continue.",
    "La sesión no se ha confirmado. Vuelve a intentarlo.": "The session was not confirmed. Please try again.",
    "LABORATORIO DE PRUEBA": "TEST LAB",
    "Las siete preguntas están juntas y son opcionales. Al enviar e identificarte, se abrirá la sala privada para probar la app.": "All seven questions appear together and are optional. Once you submit and sign in, the private room for testing the app will open.",
    "Las siete preguntas están juntas. Puedes saltarte las seis primeras; elige tu papel para personalizar la ruta privada.": "All seven questions appear together. You can skip the first six; choose your role to personalise the private route.",
    "Leer la política de privacidad": "Read the privacy policy",
    "Leer las condiciones": "Read the terms",
    "Lista para enviar de forma automática.": "Ready to send automatically.",
    "Lista para revisar. Nada se publica desde esta demostración.": "Ready to review. Nothing is published from this demo.",
    "Lo que aún hay": "What still needs",
    "Lo que queremos": "What we want",
    "Lo que se medirá en una compra local": "What will be measured in a local purchase",
    "Localidad actualizada": "Town updated",
    "Los alimentos importados que se comercializan legalmente en la UE también deben respetar sus límites máximos de residuos. La diferencia que haremos visible es que algunos países terceros pueden autorizar durante el cultivo sustancias no aprobadas para uso agrícola dentro de la Unión Europea.": "Imported food legally marketed in the EU must also comply with its maximum residue levels. The distinction we will make visible is that some non-EU countries may authorise substances during cultivation that are not approved for agricultural use within the European Union.",
    "Los clientes ya están.": "The customers are already there.",
    "Manejo y tratamientos documentados para su verificación.": "Documented farming practices and treatments for verification.",
