    "MODELO EN PRUEBA · RUTA VOLUNTARIA · IMPORTE VISIBLE ANTES DE ACEPTAR": "MODEL UNDER TEST · OPTIONAL ROUTE · AMOUNT SHOWN BEFORE ACCEPTANCE",
