    "MONTAJE": "INSTALLATION",
    "Mostramos {locality} con una comparación hecha en tu dispositivo. allwain no guarda ni envía tu posición.": "We are showing {locality}, based on a comparison made on your device. allwain does not store or send your position.",
    "Nace en Foios.": "Born in Foios.",
    "naranjas locales para 38 hogares": "local oranges for 38 households",
    "Naranjas Navel Lane Late de Foios · gran calibre · naranja intenso.": "Navel Lane Late oranges from Foios · large size · deep orange colour.",
    "Naranjas Navel Lane Late de primera calidad, gran calibre y naranja intenso, presentadas en una caja de madera en un huerto valenciano": "Premium-quality, large Navel Lane Late oranges with a deep orange colour, presented in a wooden crate in a Valencian orchard",
