    "NEGOCIOS": "BUSINESSES",
    "No": "No",
    "No ahora": "Not now",
    "No es un certificado oficial único ni afirma que un alimento importado legalmente incumpla las normas europeas.": "It is not a single official certificate and does not claim that legally imported food fails to meet European rules.",
    "No hay resultados confirmados": "No confirmed results",
    "No hemos podido abrir la sala.": "We could not open the tester room.",
