    "No hemos podido completar el envío.": "We could not complete the submission.",
    "No hemos podido completar la identificación.": "We could not complete sign-in.",
    "No hemos podido comprobar tu identidad ahora.": "We could not confirm your identity right now.",
    "No hemos podido enviar la incidencia. Inténtalo de nuevo.": "We could not submit the issue. Please try again.",
    "No hemos podido enviar la incidencia. Revisa los campos e inténtalo de nuevo.": "We could not send the issue report. Check the fields and try again.",
    "No hemos podido enviar tu opinión.": "We could not send your feedback.",
    "No hemos podido guardar este paso. Inténtalo de nuevo.": "We could not save this step. Try again.",
    "No hemos podido guardar tu opinión. Inténtalo de nuevo.": "We could not save your feedback. Please try again.",
    "No hemos podido obtener la localidad. Mantenemos de Foios a Foios.": "We could not determine your town. We will keep ‘from Foios to Foios’.",
    "No mostramos email, domicilio ni documentos. Evita incluir datos personales en las incidencias.": "We do not display your email, home address or documents. Avoid including personal data in issue reports.",
    "No puedo actuar en una cuenta ni crear, publicar, aceptar o pagar nada. Ese límite protege tu decisión. Sí puedo explicarte el recorrido, ayudarte a comparar condiciones y señalar qué debes revisar antes de que tú realices cualquier acción.": "I cannot act in an account or create, publish, accept or pay for anything. That limit protects your decision. I can explain the process, help you compare conditions and point out what to review before you take any action.",
    "No se activará la remuneración hasta que las reglas estén publicadas.": "Payment will not be activated until the rules have been published.",
    "NO SE PUDO COMPROBAR": "CHECK FAILED",
    "No son el mismo documento. Confirmación, justificante, liquidación y factura cumplen funciones distintas. allwain publicará el recorrido fiscal antes de activar pagos reales.": "They are not the same document. Confirmation, receipt, settlement and invoice serve different purposes. allwain will publish the tax process before activating real payments.",
    "NO VENDEMOS TUS DATOS": "WE DO NOT SELL YOUR DATA",
    "No. allwain no vende datos personales ni integra seguimiento publicitario. Usa datos limitados para prestar, proteger y cumplir el servicio.": "No. allwain does not sell personal data or use advertising tracking. It uses limited data to provide, protect and operate the service lawfully.",
    "No. La primera propuesta no gana automáticamente. El comprador compara precio, condiciones y encaje, y decide.": "No. The first proposal does not win automatically. The buyer compares price, terms and suitability, then decides.",
    "No. Publicar una petición y recibir propuestas no te obliga a aceptar, reservar ni pagar. Si ninguna encaja, no eliges ninguna.": "No. Publishing a request and receiving proposals does not require you to accept, reserve or pay. If none fits, you choose none.",
    "No. Ser Conector no te convierte en repartidor. Recomendar y transportar son tareas distintas; una futura entrega solo se asumirá si encaja y la aceptas expresamente.": "No. Being a Connector does not make you a delivery driver. Recommending and transporting are separate tasks; a future delivery will only be taken on if it is suitable and you expressly accept it.",
    "Nombre": "Name",
    "OBJETIVO": "TARGET",
    "Objetivo sobre el producto; el coste final mostrará entrega y ajustes.": "Product target; the final cost will show delivery and adjustments.",
    "Objetivos de la primera prueba de allwain con naranjas de Foios.": "Targets for allwain’s first test with oranges from Foios.",
    "Objetivos de la prueba: más de 300 por ciento más para quien cultiva y 50 por ciento menos para quien compra": "Test targets: more than 300 percent more for growers and 50 percent less for buyers",
    "Objetivos del reparto kilómetro cero": "Zero-mile delivery targets",
