    "Preventa próxima de naranjas Navel Lane Late de Foios. Objetivos de la prueba: más de 300 % más para quien cultiva y 50 % menos para quien compra, con un precio objetivo de 1 €/kg.": "Upcoming presale of Navel Lane Late oranges from Foios. Test targets: more than 300% more for growers and 50% less for buyers, with a target price of €1/kg.",
