    "PUEBLO": "TOWN",
    "Puedes explorar sin cuenta; identifícate para conservar el progreso.": "You can explore without an account; sign in to save your progress.",
    "Puedes ordenar las propuestas por precio, valoración o fecha y abrir cada una para revisar quién vende, el precio, la descripción y el plazo de entrega. allwain mostrará también cantidad, precio unitario, total y condiciones antes de la primera venta; comparar no te obliga a aceptar ninguna.": "You can sort proposals by price, rating or date and open each one to review the seller, price, description and delivery time. allwain will also show quantity, unit price, total and terms before the first sale; comparing does not require you to accept any proposal.",
    "Puedes participar como Comprador, Vendedor o Conector. allwain nace en Foios como laboratorio de prueba: buscamos personas que recorran la web y la primera preventa de naranjas, encuentren fallos y nos cuenten qué mejorar.": "You can take part as a Buyer, Seller or Connector. allwain was born in Foios as a test lab: we are looking for people to explore the website and the first orange presale, find problems and tell us what to improve.",
    "Puedes participar como Comprador, Vendedor o Conector. El laboratorio de allwain nace en Foios: buscamos personas que recorran la web y la primera preventa de naranjas, encuentren fallos y nos cuenten qué mejorar.": "You can take part as a Buyer, Seller or Connector. The allwain lab was born in Foios: we are looking for people to explore the website and the first orange presale, find problems and tell us what to improve.",
    "Puedes participar como Comprador, Vendedor o Conector. Las ocho pantallas y sus maquetas se exploran libremente. Para ser tester, responde la encuesta; después, la sala privada te guía para probar la app y reportar allí sus incidencias.": "You can participate as a Buyer, Seller or Connector. The eight screens and their prototypes are free to explore. To become a tester, complete the survey; the private room will then guide you through testing the app and reporting its issues there.",
