    "Sí": "Yes",
    "Si aún no tienes cuenta, abrirás el registro. Si ya estás identificado, entrarás en el recorrido guiado existente.": "If you do not have an account yet, registration will open. If you are already signed in, you will enter the existing guided tour.",
    "Si un producto se vende aquí, no hace falta traerlo de otra parte del mundo.": "If a product is sold here, there is no need to bring it from the other side of the world.",
    "Si un producto se vende aquí, no hace falta traerlo de otra parte del mundo. allwain quiere medir esa sostenibilidad real mostrando origen, ruta, recogida y entrega; la localidad del cartel solo se personaliza si das permiso al navegador y no se guarda.": "If a product is sold here, there is no need to bring it from the other side of the world. allwain wants to measure that real sustainability by showing origin, route, collection and delivery; the town on the sign is personalised only if you grant browser permission and is not stored.",
    "Si ya respondiste la encuesta con esta cuenta, recuperaremos tu sala y tu progreso.": "If you have already completed the survey with this account, we will restore your tester room and progress.",
    "Siguiente pantalla": "Next section",
