    "Sin cuotas, niveles ni ingresos garantizados. Porcentajes, condiciones y fiscalidad se publicarán antes del primer pago.": "No fees, levels or guaranteed income. Percentages, terms and tax details will be published before the first payment.",
    "Sin paso concreto": "No specific step",
