    "Sin respuestas seleccionadas.": "No answers selected.",
    "Smart TV · modelo 2025/2026": "Smart TV · 2025/2026 model",
    "SOLO CON ANÁLISIS": "ONLY WITH TEST RESULTS",
    "Solo necesarias": "Essential only",
    "Solo por operaciones válidas y terminadas, nunca por altas. Publicaremos importes, reglas y fiscalidad antes del primer pago.": "Only for valid, completed transactions, never for sign-ups. We will publish amounts, rules and tax details before the first payment.",
    "Solo por operaciones válidas y terminadas, nunca por altas. Se publicarán importes, reglas y fiscalidad antes del primer pago.": "Only for valid, completed transactions, never for sign-ups. Amounts, rules and tax treatment will be published before the first payment.",
    "Solo puedo responder sobre allwain: cómo funciona, sus roles, la prueba de Foios, privacidad, seguridad y fiscalidad.": "I can only answer questions about allwain: how it works, its roles, the Foios trial, privacy, security and taxation.",
    "Solo respondo sobre allwain: cómo funciona, sus tres papeles, la prueba de Foios, privacidad, seguridad y fiscalidad. Prueba con una pregunta concreta.": "I only answer questions about allwain: how it works, its three roles, the Foios trial, privacy, security and taxation. Try asking a specific question.",
