    "Abrir un enlace no marca nada automáticamente. En móvil, usa «Abrir la app»; en ordenador puedes usar la alternativa web. No confirmes pagos ni publiques ofertas reales durante esta primera revisión.": "L’ouverture d’un lien ne valide rien automatiquement. Sur mobile, utilisez « Ouvrir l’app » ; sur ordinateur, vous pouvez utiliser l’alternative web. Ne confirmez aucun paiement et ne publiez aucune offre réelle pendant cette première vérification.",
    "Abrir un enlace no marca nada automáticamente. No confirmes pagos ni publiques ofertas reales durante esta primera revisión.": "L’ouverture d’un lien ne valide rien automatiquement. Ne confirmez aucun paiement et ne publiez aucune offre réelle pendant cette première vérification.",
