    "Al entrar enviaremos tus respuestas automáticamente.": "Nous enverrons vos réponses automatiquement lorsque vous vous connecterez.",
    "Al entrar recuperaremos de forma segura tu recorrido de prueba.": "À votre connexion, nous restaurerons votre parcours de test en toute sécurité.",
