    "allwain — Preventa próxima de naranjas de Foios": "allwain — Prochaine prévente d’oranges de Foios",
    "allwain crece": "allwain grandit",
    "allwain empieza aquí como laboratorio real: un único producto, naranjas Navel Lane Late, y personas invitadas a probar, señalar fallos y opinar antes de la preventa.": "allwain commence ici comme un laboratoire grandeur nature : un seul produit, des oranges Navel Lane Late, et des personnes invitées à tester, signaler les problèmes et donner leur avis avant la prévente.",
    "allwain no integra publicidad ni vende datos personales. Cada acción importante necesita confirmación y cada operación conserva un rastro comprensible.": "allwain n’intègre pas de publicité et ne vend pas de données personnelles. Chaque action importante exige une confirmation et chaque opération conserve une trace compréhensible.",
    "allwain no vende datos personales ni integra seguimiento publicitario. Esta Guía no entra en tu cuenta. La conexión usa HTTPS y las sesiones son revocables: son controles reales y evolutivos, no una promesa de invulnerabilidad.": "allwain ne vend pas de données personnelles et n’intègre aucun suivi publicitaire. Ce Guide n’accède pas à votre compte. La connexion utilise HTTPS et les sessions peuvent être révoquées : ce sont des contrôles réels et évolutifs, pas une promesse d’invulnérabilité.",
    "allwain solo mostrará este distintivo cuando la documentación del lote haya sido comprobada.": "allwain n’affichera ce label qu’après vérification des documents du lot.",
    "allwain te dirá qué preparar": "allwain vous indiquera quoi préparer",
    "allwain tiene tres papeles: Comprador, que publica lo que necesita y elige; Vendedor, que responde con propuestas; y Conector, que acerca personas y negocios mediante su QR sin entrar en sus cuentas. Repartir es una función distinta y voluntaria.": "allwain comporte trois rôles : l’Acheteur, qui publie son besoin et choisit ; le Vendeur, qui répond avec des propositions ; et le Connecteur, qui rapproche les personnes et les entreprises grâce à son QR sans accéder à leurs comptes. La livraison est une fonction distincte et facultative.",
    "allwain usa HTTPS, cabeceras de seguridad y sesiones revocables. Son controles reales y evolutivos, no una promesa de invulnerabilidad.": "allwain utilise HTTPS, des en-têtes de sécurité et des sessions révocables. Ce sont des protections réelles et évolutives, pas une promesse d’invulnérabilité.",
