    "Compartes tu QR y pones la red en marcha en tu pueblo. Cuando alguien que llegó contigo completa una compra o venta válida, el modelo prevé compartir contigo parte del beneficio.": "Vous partagez votre QR et lancez le réseau dans votre commune. Lorsqu’une personne arrivée grâce à vous finalise un achat ou une vente valide, le modèle prévoit de partager avec vous une partie du bénéfice.",
