    "CON PIONEROS": "AVEC DES PIONNIERS",
    "Con tu permiso mediremos qué páginas y acciones resultan útiles. No enviamos nombres, emails, direcciones, mensajes ni textos introducidos. allwain funciona igual si eliges solo lo necesario.": "Avec votre accord, nous mesurerons les pages et actions utiles. Nous n’envoyons ni noms, ni e-mails, ni adresses, ni messages, ni textes saisis. allwain fonctionne de la même façon si vous choisissez uniquement le nécessaire.",
    "Con tu permiso mediremos qué pantallas y acciones resultan útiles. No enviamos nombres, emails, direcciones, mensajes ni textos introducidos. allwain funciona igual si eliges solo lo necesario.": "Avec votre autorisation, nous mesurerons quels écrans et quelles actions sont utiles. Nous n’envoyons ni noms, ni e-mails, ni adresses, ni messages, ni textes saisis. allwain fonctionne de la même façon si vous choisissez uniquement le nécessaire.",
