    "DESCUBRE PETICIONES": "DÉCOUVREZ LES DEMANDES",
    "Descubres clientes y peticiones, no un catálogo de productos. Respondes a los grupos que encajan con tu negocio y puedes ajustar una oferta más competitiva al volumen real.": "Vous découvrez des clients et des demandes, pas un catalogue de produits. Vous répondez aux groupes qui correspondent à votre activité et pouvez adapter une offre plus compétitive au volume réel.",
    "Desliza a «Tu zona» y prueba cómo crece una red de ejemplo.": "Faites glisser jusqu’à « Votre zone » et testez la croissance d’un réseau d’exemple.",
