    "DISTINTIVO PREVISTO PARA LOTES VERIFICADOS": "LABEL PRÉVU POUR LES LOTS VÉRIFIÉS",
    "Documentos disponibles en el idioma seleccionado.": "Documents disponibles dans la langue sélectionnée.",
    "Documentos legales disponibles en español.": "Les documents juridiques sont disponibles en espagnol.",
