    "Enviar": "Envoyer",
    "Enviar incidencia": "Envoyer le signalement",
    "Envío pendiente. Identifícate cuando quieras para registrarlo automáticamente.": "Envoi en attente. Identifiez-vous quand vous le souhaitez pour l’enregistrer automatiquement.",
    "ENVÍO PROTEGIDO": "ENVOI PROTÉGÉ",
    "Es un objetivo de la prueba, todavía no un resultado.": "C’est un objectif du test, pas encore un résultat.",
    "Escena fotográfica representativa de una persona compartiendo un QR con una comerciante y un vecino": "Scène photographique représentative d’une personne partageant un QR avec une commerçante et un voisin",
    "Escribe una pregunta…": "Écrivez une question…",
    "Ese email ya tiene cuenta. Pulsa «Ya tengo cuenta».": "Cette adresse e-mail est déjà associée à un compte. Sélectionnez « J’ai déjà un compte ».",
    "Eso es sostenibilidad real.": "C’est cela, la durabilité réelle.",
    "Español": "Español",
    "Esperando tu permiso. No guardaremos la ubicación.": "En attente de votre autorisation. Nous n’enregistrerons pas votre position.",
    "está agrupada.": "regroupée.",
    "Estado de la sesión y configuración de la prueba": "État de la session et configuration du test",
    "Estamos comprobando de forma segura si ya completaste la antesala.": "Nous vérifions de manière sécurisée si vous avez déjà terminé le questionnaire préalable.",
    "Estás interactuando con una IA. Tu pregunta y, cuando haga falta, una pregunta reciente de esta conversación pueden ser procesadas por OpenAI. No escribas nombres, direcciones, documentos, tarjetas ni datos de una operación.": "Vous interagissez avec une IA. Votre question et, si nécessaire, une question récente de cette conversation peuvent être traitées par OpenAI. Ne saisissez pas de noms, d’adresses, de documents, de données de carte ni d’informations sur une opération.",
    "Este espacio no evalúa las maquetas de la web. Te acompaña en acciones concretas dentro de la app y reúne tu progreso e incidencias en una sola cuenta.": "Cet espace n’évalue pas les maquettes du site. Il vous accompagne dans des actions précises au sein de l’app et regroupe votre progression et vos signalements dans un seul compte.",
    "Este navegador no ofrece geolocalización. Mantenemos de Foios a Foios.": "Ce navigateur ne propose pas la géolocalisation. Nous conservons « de Foios à Foios ».",
    "Estoy probando en": "Je teste sur",
    "Explora cómo se comparte el beneficio.": "Découvrez comment le bénéfice est partagé.",
    "Explorar Conector": "Explorer Connecteur",
    "FOIOS": "FOIOS",
    "Fotografías una etiqueta o explicas qué necesitas. allwain prepara un borrador para que lo revises; tú confirmas la petición, comparas respuestas y eliges.": "Vous photographiez une étiquette ou expliquez ce dont vous avez besoin. allwain prépare un brouillon que vous vérifiez ; vous confirmez la demande, comparez les réponses et choisissez.",
    "Français": "Français",
    "Frescura": "Fraîcheur",
    "FRESCURA": "FRAÎCHEUR",
    "Fuentes oficiales sobre normativa fitosanitaria europea": "Sources officielles sur la réglementation phytosanitaire européenne",
    "Gracias. Tu opinión ya está registrada y vinculada a tu identidad allwain.": "Merci. Votre avis a été enregistré et associé à votre identité allwain.",
    "Gracias. Tu opinión ya está registrada y vinculada a tu identidad de allwain.": "Merci. Votre avis a été enregistré et associé à votre identité allwain.",
    "GRUPO ABIERTO": "GROUPE OUVERT",
    "Guardando tu confirmación…": "Enregistrement de votre confirmation…",
    "Guardando…": "Enregistrement…",
    "GUÍA DE ACCIONES": "GUIDE D’ACTIONS",
