    "GUÍA IA PÚBLICA": "GUIDE IA PUBLIC",
    "Guía IA pública de allwain": "Guide IA public d’allwain",
    "Guía no disponible": "Guide indisponible",
    "Hay tres papeles en allwain: Comprador, que publica lo que necesita y elige; Vendedor, que responde con propuestas; y Conector, que acerca personas y negocios mediante su QR sin entrar en sus cuentas. Repartir es una función distinta y voluntaria.": "allwain comporte trois rôles : l’Acheteur, qui publie son besoin et choisit ; le Vendeur, qui répond avec des propositions ; et le Connecteur, qui rapproche les personnes et les entreprises grâce à son QR sans accéder à leurs comptes. La livraison est une fonction distincte et facultative.",
    "Haz crecer la red": "Développez le réseau",
    "Haz crecer una zona": "Développez une zone",
    "Haz la acción en la app. Después confírmala aquí.": "Effectuez l’action dans l’app. Confirmez-la ensuite ici.",
    "Haz una foto.": "Prenez une photo.",
