    "Identifícate para recuperar tu sala.": "Identifiez-vous pour retrouver votre espace testeur.",
    "Identifícate para validar y enviar la encuesta. Tus respuestas siguen aquí.": "Identifiez-vous pour valider et envoyer le sondage. Vos réponses sont toujours ici.",
    "Identifícate para vincular la incidencia a tu cuenta y enviarla automáticamente.": "Identifiez-vous pour associer le signalement à votre compte et l’envoyer automatiquement.",
    "Idioma": "Langue",
