    "Mostramos {locality} con una comparación hecha en tu dispositivo. allwain no guarda ni envía tu posición.": "Nous affichons {locality} à partir d’une comparaison effectuée sur votre appareil. allwain n’enregistre ni n’envoie votre position.",
