    "No es un certificado oficial único ni afirma que un alimento importado legalmente incumpla las normas europeas.": "Il ne s’agit pas d’un certificat officiel unique et cela ne signifie pas qu’un aliment importé légalement ne respecte pas les règles européennes.",
    "No hay resultados confirmados": "Aucun résultat confirmé",
    "No hemos podido abrir la sala.": "Nous n’avons pas pu ouvrir l’espace testeur.",
    "No hemos podido cerrar la sesión. Inténtalo de nuevo.": "Nous n’avons pas pu vous déconnecter. Réessayez.",
    "No hemos podido completar el envío.": "Nous n’avons pas pu terminer l’envoi.",
    "No hemos podido completar la identificación.": "Nous n’avons pas pu terminer l’identification.",
    "No hemos podido comprobar tu identidad ahora.": "Nous n’avons pas pu confirmer votre identité pour le moment.",
    "No hemos podido enviar la incidencia. Inténtalo de nuevo.": "Nous n’avons pas pu envoyer le signalement. Réessayez.",
    "No hemos podido enviar la incidencia. Revisa los campos e inténtalo de nuevo.": "Nous n’avons pas pu envoyer le signalement. Vérifiez les champs et réessayez.",
    "No hemos podido enviar tu opinión.": "Nous n’avons pas pu envoyer votre avis.",
    "No hemos podido guardar este paso. Inténtalo de nuevo.": "Nous n’avons pas pu enregistrer cette étape. Réessayez.",
    "No hemos podido guardar tu opinión. Inténtalo de nuevo.": "Nous n’avons pas pu enregistrer votre avis. Veuillez réessayer.",
    "No hemos podido obtener la localidad. Mantenemos de Foios a Foios.": "Nous n’avons pas pu déterminer votre commune. Nous conservons « de Foios à Foios ».",
    "No mostramos email, domicilio ni documentos. Evita incluir datos personales en las incidencias.": "Nous n’affichons ni votre e-mail, ni votre adresse personnelle, ni vos documents. N’incluez pas de données personnelles dans les signalements.",
    "No puedo actuar en una cuenta ni crear, publicar, aceptar o pagar nada. Ese límite protege tu decisión. Sí puedo explicarte el recorrido, ayudarte a comparar condiciones y señalar qué debes revisar antes de que tú realices cualquier acción.": "Je ne peux pas intervenir dans un compte ni créer, publier, accepter ou payer quoi que ce soit. Cette limite protège votre décision. Je peux expliquer le parcours, vous aider à comparer les conditions et indiquer ce qu’il faut vérifier avant toute action de votre part.",
    "No se activará la remuneración hasta que las reglas estén publicadas.": "La rémunération ne sera pas activée avant la publication des règles.",
    "NO SE PUDO COMPROBAR": "VÉRIFICATION IMPOSSIBLE",
    "No son el mismo documento. Confirmación, justificante, liquidación y factura cumplen funciones distintas. allwain publicará el recorrido fiscal antes de activar pagos reales.": "Il ne s’agit pas du même document. Confirmation, justificatif, règlement et facture remplissent des fonctions différentes. allwain publiera le parcours fiscal avant d’activer les paiements réels.",
    "NO VENDEMOS TUS DATOS": "NOUS NE VENDONS PAS VOS DONNÉES",
    "No. allwain no vende datos personales ni integra seguimiento publicitario. Usa datos limitados para prestar, proteger y cumplir el servicio.": "Non. allwain ne vend pas de données personnelles et n’intègre aucun suivi publicitaire. Il utilise des données limitées pour fournir, protéger et assurer la conformité du service.",
    "No. La primera propuesta no gana automáticamente. El comprador compara precio, condiciones y encaje, y decide.": "Non. La première proposition ne gagne pas automatiquement. L’acheteur compare le prix, les conditions et l’adéquation, puis décide.",
    "No. Publicar una petición y recibir propuestas no te obliga a aceptar, reservar ni pagar. Si ninguna encaja, no eliges ninguna.": "Non. Publier une demande et recevoir des propositions ne vous oblige ni à accepter, ni à réserver, ni à payer. Si aucune ne convient, vous n’en choisissez aucune.",
    "No. Ser Conector no te convierte en repartidor. Recomendar y transportar son tareas distintas; una futura entrega solo se asumirá si encaja y la aceptas expresamente.": "Non. Être Connecteur ne fait pas de vous un livreur. Recommander et transporter sont deux tâches distinctes ; une future livraison ne sera prise en charge que si elle convient et si vous l’acceptez expressément.",
