    "Puedes explorar sin cuenta; identifícate para conservar el progreso.": "Vous pouvez explorer sans compte ; identifiez-vous pour conserver votre progression.",
    "Puedes ordenar las propuestas por precio, valoración o fecha y abrir cada una para revisar quién vende, el precio, la descripción y el plazo de entrega. allwain mostrará también cantidad, precio unitario, total y condiciones antes de la primera venta; comparar no te obliga a aceptar ninguna.": "Vous pouvez trier les propositions par prix, note ou date et ouvrir chacune d’elles pour consulter le vendeur, le prix, la description et le délai de livraison. allwain affichera aussi la quantité, le prix unitaire, le total et les conditions avant la première vente ; comparer ne vous oblige à accepter aucune proposition.",
    "Puedes participar como Comprador, Vendedor o Conector. allwain nace en Foios como laboratorio de prueba: buscamos personas que recorran la web y la primera preventa de naranjas, encuentren fallos y nos cuenten qué mejorar.": "Vous pouvez participer comme Acheteur, Vendeur ou Connecteur. allwain est né à Foios comme laboratoire de test : nous recherchons des personnes pour parcourir le site et la première prévente d’oranges, repérer les problèmes et nous dire ce qui doit être amélioré.",
    "Puedes participar como Comprador, Vendedor o Conector. El laboratorio de allwain nace en Foios: buscamos personas que recorran la web y la primera preventa de naranjas, encuentren fallos y nos cuenten qué mejorar.": "Vous pouvez participer comme Acheteur, Vendeur ou Connecteur. Le laboratoire allwain est né à Foios : nous recherchons des personnes pour parcourir le site et la première prévente d’oranges, repérer les problèmes et nous dire ce qui doit être amélioré.",
    "Puedes participar como Comprador, Vendedor o Conector. Las ocho pantallas y sus maquetas se exploran libremente. Para ser tester, responde la encuesta; después, la sala privada te guía para probar la app y reportar allí sus incidencias.": "Vous pouvez participer en tant qu’Acheteur, Vendeur ou Connecteur. Les huit écrans et leurs maquettes sont en libre accès. Pour devenir testeur, répondez au questionnaire ; l’espace privé vous guidera ensuite pour tester l’app et y signaler les problèmes.",
    "QR + red visible": "QR + réseau visible",
