    "Recorre acciones concretas y vuelve aquí para registrar lo que funciona y lo que no. El progreso queda ligado a tu cuenta, nunca a tu dirección o documento de identidad.": "Effectuez des actions concrètes, puis revenez ici pour indiquer ce qui fonctionne ou non. La progression est associée à votre compte, jamais à votre adresse ni à votre pièce d’identité.",
