    "Sesión no iniciada": "Session non ouverte",
    "Sí": "Oui",
    "Si aún no tienes cuenta, abrirás el registro. Si ya estás identificado, entrarás en el recorrido guiado existente.": "Si vous n’avez pas encore de compte, le formulaire d’inscription s’ouvrira. Si vous êtes déjà identifié, vous accéderez au parcours guidé existant.",
    "Si un producto se vende aquí, no hace falta traerlo de otra parte del mundo.": "Si un produit est vendu ici, il n’est pas nécessaire de le faire venir de l’autre bout du monde.",
    "Si un producto se vende aquí, no hace falta traerlo de otra parte del mundo. allwain quiere medir esa sostenibilidad real mostrando origen, ruta, recogida y entrega; la localidad del cartel solo se personaliza si das permiso al navegador y no se guarda.": "Si un produit est vendu ici, il n’est pas nécessaire de le faire venir de l’autre bout du monde. allwain veut mesurer cette durabilité réelle en affichant l’origine, le trajet, la collecte et la livraison ; la commune indiquée sur le panneau n’est personnalisée que si vous donnez l’autorisation au navigateur et elle n’est pas enregistrée.",
    "Si ya respondiste la encuesta con esta cuenta, recuperaremos tu sala y tu progreso.": "Si vous avez déjà répondu au questionnaire avec ce compte, nous restaurerons votre espace testeur et votre progression.",
    "Siguiente pantalla": "Section suivante",
