    "allwain empieza aquí como laboratorio real: un único producto, naranjas Navel Lane Late, y personas invitadas a probar, señalar fallos y opinar antes de la preventa.": "allwain inizia qui come laboratorio reale: un solo prodotto, le arance Navel Lane Late, e persone invitate a provare, segnalare problemi e dare la propria opinione prima della prevendita.",
    "allwain no integra publicidad ni vende datos personales. Cada acción importante necesita confirmación y cada operación conserva un rastro comprensible.": "allwain non integra pubblicità né vende dati personali. Ogni azione importante richiede conferma e ogni operazione conserva una traccia comprensibile.",
    "allwain no vende datos personales ni integra seguimiento publicitario. Esta Guía no entra en tu cuenta. La conexión usa HTTPS y las sesiones son revocables: son controles reales y evolutivos, no una promesa de invulnerabilidad.": "allwain non vende dati personali né integra tracciamento pubblicitario. Questa Guida non entra nel tuo account. La connessione usa HTTPS e le sessioni sono revocabili: sono controlli reali e in evoluzione, non una promessa di invulnerabilità.",
    "allwain solo mostrará este distintivo cuando la documentación del lote haya sido comprobada.": "allwain mostrerà questo contrassegno solo dopo aver verificato la documentazione del lotto.",
    "allwain solo mostrará este distintivo cuando la documentación del lote haya sido comprobada. No es un certificado oficial único ni afirma que un alimento importado legalmente incumpla las normas europeas.": "allwain mostrerà questo contrassegno solo dopo aver verificato la documentazione del lotto. Non è un unico certificato ufficiale e non afferma che un alimento importato legalmente non rispetti le norme europee.",
    "allwain te dirá qué preparar": "allwain ti dirà cosa preparare",
    "allwain tiene tres papeles: Comprador, que publica lo que necesita y elige; Vendedor, que responde con propuestas; y Conector, que acerca personas y negocios mediante su QR sin entrar en sus cuentas. Repartir es una función distinta y voluntaria.": "allwain ha tre ruoli: l'Acquirente, che pubblica ciò di cui ha bisogno e sceglie; il Venditore, che risponde con proposte; e il Connettore, che avvicina persone e attività tramite il proprio QR senza accedere ai loro account. Consegnare è una funzione distinta e volontaria.",
    "allwain usa HTTPS, cabeceras de seguridad y sesiones revocables. Son controles reales y evolutivos, no una promesa de invulnerabilidad.": "allwain usa HTTPS, intestazioni di sicurezza e sessioni revocabili. Sono misure reali e in evoluzione, non una promessa di invulnerabilità.",
