    "DESCUBRE PETICIONES": "SCOPRI LE RICHIESTE",
    "Descubres clientes y peticiones, no un catálogo de productos. Respondes a los grupos que encajan con tu negocio y puedes ajustar una oferta más competitiva al volumen real.": "Scopri clienti e richieste, non un catalogo di prodotti. Rispondi ai gruppi adatti alla tua attività e puoi adeguare un'offerta più competitiva al volume reale.",
