    "EJEMPLO": "ESEMPIO",
    "Ejemplo de comarca: más alcance exige más soporte y reglas claras; no implica ingresos garantizados.": "Esempio di rete territoriale: una portata maggiore richiede più supporto e regole chiare; non implica guadagni garantiti.",
    "Ejemplo de red de pueblo: se atribuye quién llegó contigo y qué operaciones completa, nunca simples altas.": "Esempio di rete locale: attribuisce chi è arrivato tramite te e quali operazioni completa, mai semplici iscrizioni.",
    "Ejemplo de red inicial: el beneficio solo se compartiría cuando existan operaciones válidas y terminadas.": "Esempio di rete iniziale: il beneficio verrebbe condiviso solo in presenza di operazioni valide e concluse.",
    "Ejemplo visual: precios y respuestas no reales. Tú decides si publicas y cuál eliges.": "Esempio visivo: prezzi e risposte non sono reali. Sei tu a decidere se pubblicare e quale scegliere.",
    "El Conector acerca compradores y negocios a su red local": "Il Connettore avvicina acquirenti e attività alla propria rete locale",
    "El Conector comparte su QR, acerca compradores y negocios y activa allwain en su zona. La red que incorpora queda vinculada a él; recomendar no le da acceso a cuentas ni decisiones.": "Il Connettore condivide il proprio QR, avvicina acquirenti e attività e attiva allwain nella sua zona. La rete che coinvolge resta collegata a lui; consigliare non gli dà accesso agli account né alle decisioni.",
    "El Conector comparte su QR, acerca compradores y negocios y activa la red de allwain en su zona. La red que incorpora queda vinculada a él; recomendar no le da acceso a cuentas ni decisiones.": "Il Connettore condivide il proprio QR, avvicina acquirenti e attività e attiva la rete allwain nella sua zona. La rete che coinvolge resta collegata a lui; consigliare non gli dà accesso agli account né alle decisioni.",
    "El distintivo de allwain solo se mostrará cuando la documentación del lote haya sido comprobada.": "Il contrassegno allwain verrà mostrato solo dopo aver verificato la documentazione del lotto.",
    "El envío es automático y queda vinculado a tu cuenta.": "L’invio è automatico e viene collegato al tuo account.",
    "El laboratorio de allwain empieza aquí: un único producto, naranjas Navel Lane Late, y personas invitadas a probar, señalar fallos y opinar antes de la preventa.": "Il laboratorio allwain inizia qui: un solo prodotto, le arance Navel Lane Late, e persone invitate a provare, segnalare problemi e dare la propria opinione prima della prevendita.",
    "EL MERCADO AL REVÉS": "IL MERCATO AL CONTRARIO",
    "El modelo prevé que el Conector participe en cada compra o venta válida y terminada de su red. No cobra por altas. Los pagos, porcentajes y reglas se publicarán antes de activarse.": "Il modello prevede che il Connettore partecipi a ogni acquisto o vendita validi e conclusi della propria rete. Non viene pagato per le iscrizioni. Pagamenti, percentuali e regole saranno pubblicati prima dell'attivazione.",
    "El modelo que queremos poner a prueba": "Il modello che vogliamo mettere alla prova",
    "El objetivo de más de 300 % se comprobará frente a la referencia de origen que quede documentada en la prueba. El 50 % toma como referencia aportada 2 €/kg frente al objetivo de 1 €/kg para el producto. No son resultados confirmados. Entrega, comisiones, impuestos, embalaje, mermas y ajustes irán aparte y serán visibles.": "L'obiettivo di oltre il 300% sarà verificato rispetto al valore di riferimento all'origine documentato durante la prova. Il 50% usa come riferimento indicato 2 €/kg rispetto all'obiettivo di 1 €/kg per il prodotto. Non sono risultati confermati. Consegna, commissioni, imposte, imballaggio, cali e rettifiche saranno indicati separatamente e resteranno visibili.",
    "El primer QR y la hora confirman que el producto ha salido del punto acordado.": "Il primo QR e l’orario confermano che il prodotto ha lasciato il punto concordato.",
    "El progreso se guarda en tu cuenta de allwain.": "I progressi vengono salvati nel tuo account allwain.",
    "EL QR YA SE PUEDE COMPARTIR · LOS PAGOS AÚN NO": "IL QR SI PUÒ GIÀ CONDIVIDERE · I PAGAMENTI NON SONO ANCORA ATTIVI",
    "El recorrido que puede evitarse cuando ya existe producto local": "Il percorso che si può evitare quando il prodotto esiste già localmente",
    "el reparto remunerado se probará cuando estén cerradas sus condiciones, seguro y obligaciones fiscales.": "la consegna remunerata sarà provata quando condizioni, assicurazione e obblighi fiscali saranno definiti.",
    "El segundo QR confirma la recepción y permite cerrar la operación con un rastro comprensible.": "Il secondo QR conferma la ricezione e consente di chiudere l’operazione con una traccia comprensibile.",
    "El vendedor encuentra peticiones reales en vez de esperar solo ante un catálogo y decide a cuáles responder con una propuesta competitiva. Gana una oportunidad de venta, no una venta garantizada: el comprador compara y elige. En la prueba de naranjas, más de 300 % para quien cultiva es un objetivo por comprobar, no un resultado confirmado.": "Il venditore trova richieste reali invece di aspettare soltanto dietro un catalogo e decide a quali rispondere con una proposta competitiva. Ottiene un’opportunità di vendita, non una vendita garantita: l’acquirente confronta e sceglie. Nella prova delle arance, oltre il 300% in più per chi coltiva è un obiettivo da verificare, non un risultato confermato.",
    "El vendedor entra.": "Il venditore entra.",
    "El vendedor entra. Los clientes ya están.": "Il venditore entra. I clienti sono già lì.",
    "El vendedor podrá elegir una petición y responder con una oferta o una negociación": "Il venditore potrà scegliere una richiesta e rispondere con un'offerta o una trattativa",
    "El vendedor ve peticiones compatibles, elige cuáles le interesan y responde con una oferta o una negociación. El comprador conserva la decisión.": "Il venditore vede le richieste compatibili, sceglie quelle che gli interessano e risponde con un'offerta o una trattativa. La decisione resta all'acquirente.",
    "El visor convierte la etiqueta en una petición editable. La revisas y, con un toque, preguntas a una gran comunidad. Después comparas las respuestas.": "Il visore trasforma l'etichetta in una richiesta modificabile. La controlli e, con un tocco, la invii a una grande comunità. Poi confronti le risposte.",
    "Elegir cómo participar": "Scegli come partecipare",
    "Elige al menos una respuesta. Puedes dejar las demás en blanco.": "Scegli almeno una risposta. Puoi lasciare vuote le altre.",
    "Elige cómo participar": "Scegli come partecipare",
