    "Empezar la encuesta": "Inizia il questionario",
    "Empiezo": "Inizio",
    "En esta Guía se procesa el texto que escribes y un historial breve para entender preguntas de seguimiento. No entra en tu cuenta ni consulta pedidos, pagos o mensajes privados; allwain no vende datos personales.": "Questa Guida elabora il testo che scrivi e una breve cronologia della conversazione per capire le domande di approfondimento. Non entra nel tuo account e non consulta ordini, pagamenti o messaggi privati; allwain non vende dati personali.",
    "En este centro comercial no descubre productos: descubre peticiones y grupos de demanda. Elige cuáles puede atender y responde con una oferta más competitiva.": "In questo centro commerciale non scopre prodotti: scopre richieste e gruppi di domanda. Sceglie quali può soddisfare e risponde con un'offerta più competitiva.",
