    "ENTRA": "ENTRA",
    "Entra con la misma cuenta que usarás en la app. Tendrás una guía de acciones, progreso e incidencias sin abrir el correo.": "Accedi con lo stesso account che userai nell’app. Avrai una guida delle azioni, i progressi e le segnalazioni senza aprire l’email.",
