    "ENVÍO PROTEGIDO": "INVIO PROTETTO",
    "Es un objetivo de la prueba, todavía no un resultado.": "È un obiettivo della prova, non ancora un risultato.",
    "Escena fotográfica representativa de una persona compartiendo un QR con una comerciante y un vecino": "Scena fotografica rappresentativa di una persona che condivide un QR con una commerciante e un vicino",
