    "Ese email ya tiene cuenta. Pulsa «Ya tengo cuenta».": "Questa email ha già un account. Premi «Ho già un account».",
    "Eso es sostenibilidad real.": "Questa è sostenibilità reale.",
    "Español": "Español",
    "Esperando tu permiso. No guardaremos la ubicación.": "In attesa del tuo permesso. Non salveremo la posizione.",
    "está agrupada.": "raggruppata.",
    "Estado de la sesión y configuración de la prueba": "Stato della sessione e impostazioni della prova",
    "Estamos comprobando de forma segura si ya completaste la antesala.": "Stiamo verificando in modo sicuro se hai già completato il questionario preliminare.",
    "Estás interactuando con una IA. Tu pregunta y, cuando haga falta, una pregunta reciente de esta conversación pueden ser procesadas por OpenAI. No escribas nombres, direcciones, documentos, tarjetas ni datos de una operación.": "Stai interagendo con un'IA. La tua domanda e, quando necessario, una domanda recente di questa conversazione possono essere elaborate da OpenAI. Non scrivere nomi, indirizzi, documenti, dati di carte o di un'operazione.",
    "Este espacio no evalúa las maquetas de la web. Te acompaña en acciones concretas dentro de la app y reúne tu progreso e incidencias en una sola cuenta.": "Questo spazio non valuta i prototipi del sito. Ti accompagna in azioni specifiche nell’app e riunisce progressi e segnalazioni in un unico account.",
    "Este navegador no ofrece geolocalización. Mantenemos de Foios a Foios.": "Questo browser non offre la geolocalizzazione. Manteniamo il percorso da Foios a Foios.",
