    "Gracias. Tu opinión ya está registrada y vinculada a tu identidad allwain.": "Grazie. La tua opinione è stata registrata e collegata alla tua identità allwain.",
    "Gracias. Tu opinión ya está registrada y vinculada a tu identidad de allwain.": "Grazie. La tua opinione è stata registrata e collegata alla tua identità allwain.",
    "GRUPO ABIERTO": "GRUPPO APERTO",
