    "GUÍA IA PÚBLICA": "GUIDA IA PUBBLICA",
    "Guía IA pública de allwain": "Guida IA pubblica di allwain",
    "Guía no disponible": "Guida non disponibile",
    "Hay tres papeles en allwain: Comprador, que publica lo que necesita y elige; Vendedor, que responde con propuestas; y Conector, que acerca personas y negocios mediante su QR sin entrar en sus cuentas. Repartir es una función distinta y voluntaria.": "In allwain ci sono tre ruoli: l’Acquirente, che pubblica ciò di cui ha bisogno e sceglie; il Venditore, che risponde con proposte; e il Connettore, che avvicina persone e attività tramite il proprio QR senza accedere ai loro account. La consegna è una funzione distinta e volontaria.",
    "Haz crecer la red": "Fai crescere la rete",
    "Haz crecer una zona": "Fai crescere una zona",
    "Haz la acción en la app. Después confírmala aquí.": "Esegui l’azione nell’app. Poi confermala qui.",
