    "INGRESO LOCAL": "REDDITO LOCALE",
    "Inténtalo de nuevo en unos minutos o vuelve a la encuesta. No se ha perdido ningún dato.": "Riprova tra qualche minuto o torna al questionario. Nessun dato è andato perso.",
    "Inténtalo de nuevo en unos minutos. No se ha perdido ningún progreso.": "Riprova tra qualche minuto. Nessun progresso è andato perso.",
