    "KM 0": "KM 0",
    "La app queda bloqueada": "L’app si blocca",
    "La contraseña debe tener al menos 12 caracteres.": "La password deve contenere almeno 12 caratteri.",
    "La contraseña viaja cifrada y no se guarda en esta página.": "La password viene trasmessa in forma cifrata e non viene salvata in questa pagina.",
    "La demanda y el volumen deben encajar": "Domanda e volume devono combaciare",
    "La demanda ya": "La domanda è già",
    "La demanda ya está agrupada.": "La domanda è già raggruppata.",
    "La encuesta es la antesala de esta academia. Después de enviarla con tu cuenta, volverás aquí automáticamente.": "Il questionario è il primo passo per accedere a questa accademia di test. Dopo averlo inviato con il tuo account, tornerai qui automaticamente.",
    "La encuesta solo se registra vinculada a una identidad allwain. Al entrar, se enviará automáticamente sin abrir tu correo.": "Il sondaggio viene registrato solo se collegato a un'identità allwain. Dopo l'accesso verrà inviato automaticamente senza aprire il programma di posta.",
    "La encuesta y tu identidad abren esta sala.": "Il questionario e la tua identità aprono questa sala.",
    "La entrega cierra la ruta.": "La consegna chiude il percorso.",
    "La entrega puede remunerar a alguien cercano.": "La consegna può remunerare una persona del posto.",
    "La fiscalidad del Conector aún no está activada. Su participación se plantea solo sobre compras o ventas válidas y terminadas de su red, nunca por altas; porcentajes, impuestos, justificantes y liquidaciones se publicarán antes del primer pago.": "La fiscalità del Connettore non è ancora attiva. La sua partecipazione è prevista solo su acquisti o vendite validi e conclusi della propria rete, mai sulle iscrizioni; percentuali, imposte, documenti giustificativi e liquidazioni saranno pubblicati prima del primo pagamento.",
    "La incidencia llega automáticamente al panel de soporte y queda vinculada a tu cuenta. No se abre el correo.": "La segnalazione viene inviata automaticamente al pannello di assistenza e collegata al tuo account. Non si apre l’email.",
    "La misma identidad enlaza la encuesta, este recorrido y tus incidencias.": "La stessa identità collega il questionario, questo percorso e le tue segnalazioni.",
    "La persona que reparte ve distancia, importe y condiciones. Esta maqueta no inicia ninguna ruta.": "Chi effettua la consegna vede distanza, importo e condizioni. Questo prototipo non avvia alcun percorso.",
    "La presentación funciona sin JavaScript. Para usar la Guía pública necesitas activarlo.": "La presentazione funziona senza JavaScript. Per usare la Guida pubblica devi attivarlo.",
    "LA PREVENTA AÚN NO HA EMPEZADO": "LA PREVENDITA NON È ANCORA INIZIATA",
    "La preventa aún no se ha abierto porque esta primera prueba debe cerrar condiciones de participación, entrega, trazabilidad y soporte. La web pública explica el modelo con maquetas libres; la prueba y sus incidencias se realizan en la app desde la sala privada. Cuando esos puntos estén verificados, se publicará una fecha.": "La prevendita non è ancora aperta perché questa prima prova deve definire le condizioni di partecipazione, consegna, tracciabilità e assistenza. Il sito pubblico spiega il modello con prototipi liberamente esplorabili; la prova e le segnalazioni si svolgono nell’app dalla sala privata. Quando questi punti saranno stati verificati, verrà pubblicata una data.",
    "La preventa es próxima, pero todavía no hay una fecha pública confirmada. Empezará con naranjas Navel Lane Late de Foios a 1 €/kg como precio objetivo; antes se publicarán las condiciones de entrega y participación.": "La prevendita è prossima, ma non c'è ancora una data pubblica confermata. Inizierà con le arance Navel Lane Late di Foios a 1 €/kg come prezzo obiettivo; prima saranno pubblicate le condizioni di consegna e partecipazione.",
    "La preventa y la primera operación siguen pendientes.": "La prevendita e la prima operazione devono ancora avvenire.",
    "La primera prueba": "La prima prova",
    "La prueba de las naranjas": "La prova delle arance",
    "La prueba empezará con un único producto: naranjas Navel Lane Late de Foios, de calidad, gran calibre y naranja intenso. Un euro por kilo es el objetivo del producto; la preventa y la primera venta siguen pendientes. Más de 300 % más para quien cultiva y 50 % menos para quien compra son objetivos comparados con las referencias aportadas, no resultados confirmados.": "La prova inizierà con un unico prodotto: arance Navel Lane Late di Foios, di qualità, grande calibro e arancione intenso. Un euro al chilo è l'obiettivo per il prodotto; la prevendita e la prima vendita devono ancora avvenire. Oltre il 300% in più per chi coltiva e il 50% in meno per chi acquista sono obiettivi confrontati con i riferimenti forniti, non risultati confermati.",
    "La recogida deja una prueba verificable.": "Il ritiro lascia una prova verificabile.",
    "La red de allwain crece": "La rete allwain cresce",
    "La ruta debe poder demostrarse de principio a fin, sin prometer resultados antes de probarla.": "Il percorso deve poter essere dimostrato dall'inizio alla fine, senza promettere risultati prima della prova.",
    "La ruta une dos puntos cercanos.": "Il percorso unisce due punti vicini.",
    "La sesión ha caducado. Identifícate de nuevo para continuar.": "La sessione è scaduta. Accedi di nuovo per continuare.",
    "La sesión no se ha confirmado. Vuelve a intentarlo.": "La sessione non è stata confermata. Riprova.",
    "LABORATORIO DE PRUEBA": "LABORATORIO DI PROVA",
    "Las siete preguntas están juntas y son opcionales. Al enviar e identificarte, se abrirá la sala privada para probar la app.": "Le sette domande sono tutte insieme e facoltative. Dopo l’invio e l’accesso, si aprirà la sala privata per provare l’app.",
    "Las siete preguntas están juntas. Puedes saltarte las seis primeras; elige tu papel para personalizar la ruta privada.": "Le sette domande sono tutte insieme. Puoi saltare le prime sei; scegli il tuo ruolo per personalizzare il percorso privato.",
