    "Localidad actualizada": "Località aggiornata",
    "Los alimentos importados que se comercializan legalmente en la UE también deben respetar sus límites máximos de residuos. La diferencia que haremos visible es que algunos países terceros pueden autorizar durante el cultivo sustancias no aprobadas para uso agrícola dentro de la Unión Europea.": "Anche gli alimenti importati commercializzati legalmente nell'UE devono rispettarne i limiti massimi di residui. La differenza che renderemo visibile è che alcuni Paesi terzi possono autorizzare durante la coltivazione sostanze non approvate per l'uso agricolo nell'Unione europea.",
    "Los clientes ya están.": "I clienti sono già lì.",
