    "MONTAJE": "INSTALLAZIONE",
    "Mostramos {locality} con una comparación hecha en tu dispositivo. allwain no guarda ni envía tu posición.": "Mostriamo {locality} sulla base di un confronto eseguito sul tuo dispositivo. allwain non salva né invia la tua posizione.",
