    "Naranjas Navel Lane Late de Foios · gran calibre · naranja intenso.": "Arance Navel Lane Late di Foios · grande calibro · arancione intenso.",
    "Naranjas Navel Lane Late de primera calidad, gran calibre y naranja intenso, presentadas en una caja de madera en un huerto valenciano": "Arance Navel Lane Late di prima qualità, grande calibro e arancione intenso, presentate in una cassetta di legno in un agrumeto valenciano",
