    "No": "No",
    "No ahora": "Non ora",
    "No es un certificado oficial único ni afirma que un alimento importado legalmente incumpla las normas europeas.": "Non è un unico certificato ufficiale e non afferma che un alimento importato legalmente non rispetti le norme europee.",
    "No hay resultados confirmados": "Non ci sono risultati confermati",
    "No hemos podido abrir la sala.": "Non siamo riusciti ad aprire la sala tester.",
    "No hemos podido cerrar la sesión. Inténtalo de nuevo.": "Non siamo riusciti a disconnetterti. Riprova.",
    "No hemos podido completar el envío.": "Non è stato possibile completare l'invio.",
    "No hemos podido completar la identificación.": "Non è stato possibile completare l'identificazione.",
    "No hemos podido comprobar tu identidad ahora.": "Non è stato possibile verificare la tua identità in questo momento.",
    "No hemos podido enviar la incidencia. Inténtalo de nuevo.": "Non siamo riusciti a inviare la segnalazione. Riprova.",
    "No hemos podido enviar la incidencia. Revisa los campos e inténtalo de nuevo.": "Non siamo riusciti a inviare la segnalazione. Controlla i campi e riprova.",
    "No hemos podido enviar tu opinión.": "Non è stato possibile inviare la tua opinione.",
    "No hemos podido guardar este paso. Inténtalo de nuevo.": "Non siamo riusciti a salvare questo passaggio. Riprova.",
    "No hemos podido guardar tu opinión. Inténtalo de nuevo.": "Non è stato possibile salvare la tua opinione. Riprova.",
    "No hemos podido obtener la localidad. Mantenemos de Foios a Foios.": "Non è stato possibile ottenere la località. Manteniamo il percorso da Foios a Foios.",
    "No mostramos email, domicilio ni documentos. Evita incluir datos personales en las incidencias.": "Non mostriamo email, indirizzo di casa o documenti. Evita di inserire dati personali nelle segnalazioni.",
    "No puedo actuar en una cuenta ni crear, publicar, aceptar o pagar nada. Ese límite protege tu decisión. Sí puedo explicarte el recorrido, ayudarte a comparar condiciones y señalar qué debes revisar antes de que tú realices cualquier acción.": "Non posso agire in un account né creare, pubblicare, accettare o pagare nulla. Questo limite protegge la tua decisione. Posso spiegarti il percorso, aiutarti a confrontare le condizioni e indicarti cosa verificare prima che tu compia qualsiasi azione.",
    "No se activará la remuneración hasta que las reglas estén publicadas.": "La remunerazione non sarà attivata finché le regole non saranno pubblicate.",
    "NO SE PUDO COMPROBAR": "VERIFICA NON RIUSCITA",
    "No son el mismo documento. Confirmación, justificante, liquidación y factura cumplen funciones distintas. allwain publicará el recorrido fiscal antes de activar pagos reales.": "Non sono lo stesso documento. Conferma, giustificativo, liquidazione e fattura hanno funzioni diverse. allwain pubblicherà il percorso fiscale prima di attivare pagamenti reali.",
    "NO VENDEMOS TUS DATOS": "NON VENDIAMO I TUOI DATI",
    "No. allwain no vende datos personales ni integra seguimiento publicitario. Usa datos limitados para prestar, proteger y cumplir el servicio.": "No. allwain non vende dati personali né integra tracciamento pubblicitario. Usa dati limitati per fornire, proteggere e gestire il servizio nel rispetto degli obblighi.",
    "No. La primera propuesta no gana automáticamente. El comprador compara precio, condiciones y encaje, y decide.": "No. La prima proposta non vince automaticamente. L'acquirente confronta prezzo, condizioni e adeguatezza, poi decide.",
    "No. Publicar una petición y recibir propuestas no te obliga a aceptar, reservar ni pagar. Si ninguna encaja, no eliges ninguna.": "No. Pubblicare una richiesta e ricevere proposte non ti obbliga ad accettare, prenotare o pagare. Se nessuna è adatta, non ne scegli nessuna.",
    "No. Ser Conector no te convierte en repartidor. Recomendar y transportar son tareas distintas; una futura entrega solo se asumirá si encaja y la aceptas expresamente.": "No. Essere Connettore non ti rende un corriere. Consigliare e trasportare sono attività diverse; una futura consegna sarà assunta solo se è adatta e la accetti espressamente.",
    "Nombre": "Nome",
    "OBJETIVO": "OBIETTIVO",
    "Objetivo sobre el producto; el coste final mostrará entrega y ajustes.": "Obiettivo riferito al prodotto; il costo finale mostrerà consegna e rettifiche.",
    "Objetivos de la primera prueba de allwain con naranjas de Foios.": "Obiettivi della prima prova di allwain con le arance di Foios.",
    "Objetivos de la prueba: más de 300 por ciento más para quien cultiva y 50 por ciento menos para quien compra": "Obiettivi della prova: oltre il 300 per cento in più per chi coltiva e il 50 per cento in meno per chi acquista",
    "Objetivos del reparto kilómetro cero": "Obiettivi della consegna a chilometro zero",
    "OBJETIVOS POR COMPROBAR": "OBIETTIVI DA VERIFICARE",
    "Objetivos por comprobar: más de 300 % más para quien cultiva, 50 % menos para quien compra y 1 €/kg para el producto.": "Obiettivi da verificare: oltre il 300% in più per chi coltiva, il 50% in meno per chi acquista e 1 €/kg per il prodotto.",
    "observador": "osservatore",
