    "Oferta de ejemplo a {price}, preparada para revisar. No se ha enviado.": "Offerta di esempio a {price}, pronta da controllare. Non è stata inviata.",
    "Oferta de ejemplo preparada para revisar": "Offerta di esempio pronta da controllare",
    "OFERTAR": "FARE UN'OFFERTA",
    "og:locale": "it_IT",
    "Opcional. Tu navegador pedirá permiso y comparará la posición con localidades cercanas dentro del dispositivo. allwain no la guarda ni la envía.": "Facoltativo. Il browser chiederà il permesso e confronterà la posizione con le località vicine direttamente sul dispositivo. allwain non la salva né la invia.",
