    "Parece que has incluido un dato personal. Haz una pregunta general sin nombres, dirección, correo, teléfono, documentos, tarjetas ni datos de una operación.": "Sembra che tu abbia incluso un dato personale. Fai una domanda generale senza nomi, indirizzo, email, telefono, documenti, carte o dati di un'operazione.",
