    "PUEBLO": "TERRITORIO",
    "Puedes explorar sin cuenta; identifícate para conservar el progreso.": "Puoi esplorare senza account; accedi per conservare i progressi.",
    "Puedes ordenar las propuestas por precio, valoración o fecha y abrir cada una para revisar quién vende, el precio, la descripción y el plazo de entrega. allwain mostrará también cantidad, precio unitario, total y condiciones antes de la primera venta; comparar no te obliga a aceptar ninguna.": "Puoi ordinare le proposte per prezzo, valutazione o data e aprirle per controllare chi vende, il prezzo, la descrizione e i tempi di consegna. Prima della prima vendita allwain mostrerà anche quantità, prezzo unitario, totale e condizioni; confrontare non ti obbliga ad accettarne nessuna.",
    "Puedes participar como Comprador, Vendedor o Conector. allwain nace en Foios como laboratorio de prueba: buscamos personas que recorran la web y la primera preventa de naranjas, encuentren fallos y nos cuenten qué mejorar.": "Puoi partecipare come Acquirente, Venditore o Connettore. allwain nasce a Foios come laboratorio di prova: cerchiamo persone che esplorino il sito e la prima prevendita di arance, trovino problemi e ci dicano cosa migliorare.",
    "Puedes participar como Comprador, Vendedor o Conector. El laboratorio de allwain nace en Foios: buscamos personas que recorran la web y la primera preventa de naranjas, encuentren fallos y nos cuenten qué mejorar.": "Puoi partecipare come Acquirente, Venditore o Connettore. Il laboratorio allwain nasce a Foios: cerchiamo persone che esplorino il sito e la prima prevendita di arance, trovino problemi e ci dicano cosa migliorare.",
    "Puedes participar como Comprador, Vendedor o Conector. Las ocho pantallas y sus maquetas se exploran libremente. Para ser tester, responde la encuesta; después, la sala privada te guía para probar la app y reportar allí sus incidencias.": "Puoi partecipare come Acquirente, Venditore o Connettore. Le otto schermate e i relativi prototipi si possono esplorare liberamente. Per diventare tester, rispondi al questionario; la sala privata ti guiderà poi nella prova dell’app e nella segnalazione dei problemi.",
    "QR + red visible": "QR + rete visibile",
    "que resolver.": "da risolvere.",
