    "Quedan vinculados": "Restano collegati",
    "Queremos probar una ruta corta que conserve la frescura, genere ingresos locales y deje cada recogida y entrega verificadas.": "Vogliamo provare un percorso breve che preservi la freschezza, generi reddito locale e renda verificabili ogni ritiro e consegna.",
