    "Recorre acciones concretas y vuelve aquí para registrar lo que funciona y lo que no. El progreso queda ligado a tu cuenta, nunca a tu dirección o documento de identidad.": "Prova azioni concrete e torna qui per registrare cosa funziona e cosa no. I progressi sono collegati al tuo account, mai al tuo indirizzo o documento di identità.",
