    "Sí": "Sì",
    "Si aún no tienes cuenta, abrirás el registro. Si ya estás identificado, entrarás en el recorrido guiado existente.": "Se non hai ancora un account, si aprirà la registrazione. Se hai già effettuato l'accesso, entrerai nel percorso guidato esistente.",
    "Si un producto se vende aquí, no hace falta traerlo de otra parte del mundo.": "Se un prodotto si vende qui, non serve portarlo dall'altra parte del mondo.",
    "Si un producto se vende aquí, no hace falta traerlo de otra parte del mundo. allwain quiere medir esa sostenibilidad real mostrando origen, ruta, recogida y entrega; la localidad del cartel solo se personaliza si das permiso al navegador y no se guarda.": "Se un prodotto si vende qui, non serve portarlo dall’altra parte del mondo. allwain vuole misurare questa sostenibilità reale mostrando origine, percorso, ritiro e consegna; la località del cartello viene personalizzata solo se autorizzi il browser e non viene salvata.",
    "Si ya respondiste la encuesta con esta cuenta, recuperaremos tu sala y tu progreso.": "Se hai già risposto al questionario con questo account, recupereremo la tua sala tester e i progressi.",
