    "Solo por operaciones válidas y terminadas, nunca por altas. Publicaremos importes, reglas y fiscalidad antes del primer pago.": "Solo per operazioni valide e concluse, mai per le iscrizioni. Pubblicheremo importi, regole e fiscalità prima del primo pagamento.",
    "Solo por operaciones válidas y terminadas, nunca por altas. Se publicarán importes, reglas y fiscalidad antes del primer pago.": "Solo per operazioni valide e concluse, mai per semplici iscrizioni. Importi, regole e trattamento fiscale saranno pubblicati prima del primo pagamento.",
    "Solo puedo responder sobre allwain: cómo funciona, sus roles, la prueba de Foios, privacidad, seguridad y fiscalidad.": "Posso rispondere solo a domande su allwain: come funziona, i suoi ruoli, la prova di Foios, privacy, sicurezza e fiscalità.",
    "Solo respondo sobre allwain: cómo funciona, sus tres papeles, la prueba de Foios, privacidad, seguridad y fiscalidad. Prueba con una pregunta concreta.": "Rispondo solo su allwain: come funziona, i suoi tre ruoli, la prova di Foios, privacy, sicurezza e fiscalità. Prova con una domanda specifica.",
    "Solo se afirmará para un lote cuando exista evidencia analítica suficiente.": "Sarà dichiarato per un lotto solo in presenza di prove analitiche sufficienti.",
