    "Abrir un enlace no marca nada automáticamente. En móvil, usa «Abrir la app»; en ordenador puedes usar la alternativa web. No confirmes pagos ni publiques ofertas reales durante esta primera revisión.": "打开链接不会自动标记任何步骤。在移动设备上，请使用“打开应用”；在电脑上，可以使用 Web 版入口。首次检查期间，请勿确认付款或发布真实报价。",
    "Abrir un enlace no marca nada automáticamente. No confirmes pagos ni publiques ofertas reales durante esta primera revisión.": "打开链接不会自动标记任何步骤。首次检查期间，请勿确认付款或发布真实报价。",
