    "allwain": "allwain",
    "allwain — Preventa próxima de naranjas de Foios": "allwain — Foios 橙子预售即将开启",
    "allwain crece": "allwain 通过",
    "allwain crece de boca en boca.": "allwain 通过口碑连接更多人。",
    "allwain empieza aquí como laboratorio real: un único producto, naranjas Navel Lane Late, y personas invitadas a probar, señalar fallos y opinar antes de la preventa.": "allwain 从这里开始，把 Foios 作为真实试验场：先测试一种产品——Navel Lane Late 橙子，并邀请大家在预售前体验、指出问题并提出意见。",
    "allwain no integra publicidad ni vende datos personales. Cada acción importante necesita confirmación y cada operación conserva un rastro comprensible.": "allwain 不植入广告，也不出售个人数据。每项重要操作都需要确认，每笔交易都会保留清晰易懂的记录。",
    "allwain no vende datos personales ni integra seguimiento publicitario. Esta Guía no entra en tu cuenta. La conexión usa HTTPS y las sesiones son revocables: son controles reales y evolutivos, no una promesa de invulnerabilidad.": "allwain 不出售个人数据，也不使用广告跟踪。本指南无法进入你的账户。连接使用 HTTPS，会话可以撤销：这些是真实且持续完善的控制措施，并非绝对安全的承诺。",
    "allwain solo mostrará este distintivo cuando la documentación del lote haya sido comprobada.": "allwain 仅会在批次文件核验后显示此标识。",
    "allwain solo mostrará este distintivo cuando la documentación del lote haya sido comprobada. No es un certificado oficial único ni afirma que un alimento importado legalmente incumpla las normas europeas.": "allwain 仅会在批次文件核验后显示此标识。它不是某一种官方认证，也不表示合法进口的食品不符合欧盟标准。",
    "allwain te dirá qué preparar": "allwain 会告诉你要准备什么",
    "allwain tiene tres papeles: Comprador, que publica lo que necesita y elige; Vendedor, que responde con propuestas; y Conector, que acerca personas y negocios mediante su QR sin entrar en sus cuentas. Repartir es una función distinta y voluntaria.": "allwain 有三种角色：买家发布需求并作出选择；卖家通过方案回应；连接者通过自己的二维码连接个人和商户，但不能进入他们的账户。配送是另一项独立且自愿的功能。",
    "allwain usa HTTPS, cabeceras de seguridad y sesiones revocables. Son controles reales y evolutivos, no una promesa de invulnerabilidad.": "allwain 使用 HTTPS、安全响应头和可撤销会话。这些是真实且持续演进的防护措施，并非绝对安全的承诺。",
