    "Compartes tu QR y pones la red en marcha en tu pueblo. Cuando alguien que llegó contigo completa una compra o venta válida, el modelo prevé compartir contigo parte del beneficio.": "你分享二维码，让网络在本地运转起来。当通过你加入的人完成一笔有效购买或销售时，该模式计划与你分享部分收益。",
