    "Con tu permiso mediremos qué páginas y acciones resultan útiles. No enviamos nombres, emails, direcciones, mensajes ni textos introducidos. allwain funciona igual si eliges solo lo necesario.": "经你许可，我们会统计哪些页面和操作有帮助。我们不会发送姓名、邮箱、地址、消息或输入的文字。即使你只允许必要功能，allwain 也会照常运行。",
    "Con tu permiso mediremos qué pantallas y acciones resultan útiles. No enviamos nombres, emails, direcciones, mensajes ni textos introducidos. allwain funciona igual si eliges solo lo necesario.": "经你同意，我们会衡量哪些页面和操作有用。我们不会发送姓名、电子邮件、地址、消息或你输入的文本。即使你只选择必要功能，allwain 也会照常运行。",
