    "Encuesta rápida": "快速调查",
    "ENCUESTA RÁPIDA · MENOS DE 1 MINUTO": "快速调查 · 不到 1 分钟",
    "English": "English",
    "ENTRA": "进入",
    "Entra con la misma cuenta que usarás en la app. Tendrás una guía de acciones, progreso e incidencias sin abrir el correo.": "使用你将在应用中使用的同一账户登录。无需打开邮箱，即可查看操作指南、测试进度并报告问题。",
    "Entra con tu cuenta de allwain para guardar el recorrido y enviar incidencias.": "登录 allwain 账户以保存测试进度并提交问题。",
    "Entra con tu cuenta, vuelve al inicio y comprueba que entiendes cómo cambiar de espacio.": "使用账户登录，返回首页，并检查你是否清楚如何切换不同空间。",
