    "Enviar incidencia": "提交问题",
    "Envío pendiente. Identifícate cuando quieras para registrarlo automáticamente.": "提交仍在等待中。你可以随时验证身份，之后系统会自动记录。",
    "ENVÍO PROTEGIDO": "安全提交",
    "Es un objetivo de la prueba, todavía no un resultado.": "这是测试目标，尚不是已取得的结果。",
    "Escena fotográfica representativa de una persona compartiendo un QR con una comerciante y un vecino": "一人与商户和邻居分享二维码的场景照片",
    "Escribe una pregunta…": "输入问题……",
    "Ese email ya tiene cuenta. Pulsa «Ya tengo cuenta».": "该邮箱已有账户，请选择“我已有账户”。",
    "Eso es sostenibilidad real.": "这才是真正的可持续。",
    "Español": "Español",
    "Esperando tu permiso. No guardaremos la ubicación.": "正在等待你的许可。我们不会保存位置信息。",
    "está agrupada.": "汇集成组。",
    "Estado de la sesión y configuración de la prueba": "会话状态与测试设置",
    "Estamos comprobando de forma segura si ya completaste la antesala.": "我们正在安全地检查你是否已完成前置问卷。",
    "Estás interactuando con una IA. Tu pregunta y, cuando haga falta, una pregunta reciente de esta conversación pueden ser procesadas por OpenAI. No escribas nombres, direcciones, documentos, tarjetas ni datos de una operación.": "你正在与 AI 互动。你的问题，以及在必要时本次对话中的一个近期问题，可能会由 OpenAI 处理。请勿输入姓名、地址、证件、银行卡信息或交易数据。",
    "Este espacio no evalúa las maquetas de la web. Te acompaña en acciones concretas dentro de la app y reúne tu progreso e incidencias en una sola cuenta.": "此空间不评估网站原型。它会引导你在应用内完成具体操作，并将测试进度与问题报告统一保存在同一账户中。",
    "Este navegador no ofrece geolocalización. Mantenemos de Foios a Foios.": "此浏览器不支持地理定位。将继续显示从 Foios 到 Foios。",
    "Estoy probando en": "我正在使用",
    "Explora cómo se comparte el beneficio.": "了解收益如何分享。",
    "Explorar Conector": "探索连接者功能",
    "FOIOS": "FOIOS",
    "Fotografías una etiqueta o explicas qué necesitas. allwain prepara un borrador para que lo revises; tú confirmas la petición, comparas respuestas y eliges.": "你可以拍摄标签，也可以说明自己需要什么。allwain 会生成草稿供你核对；由你确认需求、比较回复并作出选择。",
