    "Gracias. Tu opinión ya está registrada y vinculada a tu identidad allwain.": "谢谢。你的意见已记录，并关联到你的 allwain 身份。",
    "Gracias. Tu opinión ya está registrada y vinculada a tu identidad de allwain.": "谢谢。你的意见已记录，并关联到你的 allwain 身份。",
    "GRUPO ABIERTO": "开放群组",
