    "GUÍA DE ACCIONES": "操作指南",
    "GUÍA DE ACCIONES EN LA APP": "应用操作测试指南",
    "GUÍA IA PÚBLICA": "公共 AI 指南",
    "Guía IA pública de allwain": "allwain 公共 AI 指南",
    "Guía no disponible": "指南暂不可用",
    "Hay tres papeles en allwain: Comprador, que publica lo que necesita y elige; Vendedor, que responde con propuestas; y Conector, que acerca personas y negocios mediante su QR sin entrar en sus cuentas. Repartir es una función distinta y voluntaria.": "allwain 有三种角色：买家发布需求并作出选择；卖家通过方案回应；连接者通过自己的二维码连接个人和商户，但不能进入他们的账户。配送是另一项独立且自愿的功能。",
    "Haz crecer la red": "发展网络",
    "Haz crecer una zona": "发展一个区域",
    "Haz la acción en la app. Después confírmala aquí.": "请先在应用中完成操作，然后在这里确认。",
