    "La encuesta es la antesala de esta academia. Después de enviarla con tu cuenta, volverás aquí automáticamente.": "问卷是进入测试学院的第一步。使用账户提交后，你会自动返回这里。",
    "La encuesta solo se registra vinculada a una identidad allwain. Al entrar, se enviará automáticamente sin abrir tu correo.": "调查仅在关联 allwain 身份后记录。登录后将自动提交，不会打开邮件应用。",
    "La encuesta y tu identidad abren esta sala.": "完成问卷并确认身份后即可进入此空间。",
    "La entrega cierra la ruta.": "配送完成后，路线闭环。",
    "La entrega puede remunerar a alguien cercano.": "配送可以为附近的人带来收入。",
    "La fiscalidad del Conector aún no está activada. Su participación se plantea solo sobre compras o ventas válidas y terminadas de su red, nunca por altas; porcentajes, impuestos, justificantes y liquidaciones se publicarán antes del primer pago.": "连接者的税务机制尚未启用。其收益仅针对网络中有效且已完成的购买或销售，绝不按注册人数计算；比例、税费、凭证和结算方式会在首次付款前公布。",
    "La incidencia llega automáticamente al panel de soporte y queda vinculada a tu cuenta. No se abre el correo.": "问题报告会自动发送到支持后台并关联你的账户，不会打开邮件应用。",
    "La misma identidad enlaza la encuesta, este recorrido y tus incidencias.": "同一身份会关联问卷、测试流程和问题报告。",
    "La persona que reparte ve distancia, importe y condiciones. Esta maqueta no inicia ninguna ruta.": "配送人员可以看到距离、报酬和条件。此原型不会启动任何实际路线。",
    "La presentación funciona sin JavaScript. Para usar la Guía pública necesitas activarlo.": "此页面无需 JavaScript 也可浏览；如需使用公共指南，请启用 JavaScript。",
    "LA PREVENTA AÚN NO HA EMPEZADO": "预售尚未开始",
    "La preventa aún no se ha abierto porque esta primera prueba debe cerrar condiciones de participación, entrega, trazabilidad y soporte. La web pública explica el modelo con maquetas libres; la prueba y sus incidencias se realizan en la app desde la sala privada. Cuando esos puntos estén verificados, se publicará una fecha.": "预售尚未开放，因为首次测试仍需明确参与、配送、可追溯性和支持条件。公开网站通过可自由体验的原型介绍这一模式；测试和问题反馈则需从私人测试空间进入应用完成。上述要点验证完毕后才会公布日期。",
    "La preventa es próxima, pero todavía no hay una fecha pública confirmada. Empezará con naranjas Navel Lane Late de Foios a 1 €/kg como precio objetivo; antes se publicarán las condiciones de entrega y participación.": "预售即将开启，但目前还没有公开确认的日期。首个产品将是 Foios 的 Navel Lane Late 橙子，目标价为 1 欧元/千克；配送和参与条件会在开始前公布。",
    "La preventa y la primera operación siguen pendientes.": "预售和首笔交易尚未进行。",
    "La primera prueba": "首次测试",
    "La prueba de las naranjas": "橙子测试",
    "La prueba empezará con un único producto: naranjas Navel Lane Late de Foios, de calidad, gran calibre y naranja intenso. Un euro por kilo es el objetivo del producto; la preventa y la primera venta siguen pendientes. Más de 300 % más para quien cultiva y 50 % menos para quien compra son objetivos comparados con las referencias aportadas, no resultados confirmados.": "测试将从一种产品开始：Foios 的优质、大果径、色泽浓郁的 Navel Lane Late 橙子。每千克 1 欧元是产品目标价；预售和首笔销售尚未进行。种植者收益提高 300% 以上、购买者少花 50%，都是相对于所提供参考值的测试目标，并非已确认结果。",
    "La recogida deja una prueba verificable.": "取货会留下可验证的凭证。",
    "La red de allwain crece": "allwain 网络不断发展",
    "La ruta debe poder demostrarse de principio a fin, sin prometer resultados antes de probarla.": "整条路线必须从头到尾可验证，在完成测试前不承诺结果。",
    "La ruta une dos puntos cercanos.": "路线连接两个相近地点。",
    "La sesión ha caducado. Identifícate de nuevo para continuar.": "会话已过期，请重新登录以继续。",
    "La sesión no se ha confirmado. Vuelve a intentarlo.": "会话尚未确认，请重试。",
    "LABORATORIO DE PRUEBA": "测试实验室",
    "Las siete preguntas están juntas y son opcionales. Al enviar e identificarte, se abrirá la sala privada para probar la app.": "七个问题会同时显示，且均为选答。提交并登录后，应用测试的私人空间将会打开。",
    "Las siete preguntas están juntas. Puedes saltarte las seis primeras; elige tu papel para personalizar la ruta privada.": "七个问题会同时显示。你可以跳过前六题；请选择你的角色，以个性化私人测试路线。",
    "Leer la política de privacidad": "阅读隐私政策",
    "Leer las condiciones": "阅读条款",
