    "Lo que se medirá en una compra local": "本地购买将衡量的内容",
    "Localidad actualizada": "地点已更新",
    "Los alimentos importados que se comercializan legalmente en la UE también deben respetar sus límites máximos de residuos. La diferencia que haremos visible es que algunos países terceros pueden autorizar durante el cultivo sustancias no aprobadas para uso agrícola dentro de la Unión Europea.": "在欧盟合法销售的进口食品同样必须符合欧盟规定的最大残留限量。我们要清楚呈现的区别在于：一些第三国可能允许在种植过程中使用未获欧盟批准用于农业的物质。",
    "Los clientes ya están.": "客户已经在这里。",
