    "No hemos podido guardar tu opinión. Inténtalo de nuevo.": "无法保存你的意见，请重试。",
    "No hemos podido obtener la localidad. Mantenemos de Foios a Foios.": "无法获取地点。将继续显示从 Foios 到 Foios。",
    "No mostramos email, domicilio ni documentos. Evita incluir datos personales en las incidencias.": "我们不会显示邮箱、住址或证件信息。请勿在问题报告中填写个人数据。",
    "No puedo actuar en una cuenta ni crear, publicar, aceptar o pagar nada. Ese límite protege tu decisión. Sí puedo explicarte el recorrido, ayudarte a comparar condiciones y señalar qué debes revisar antes de que tú realices cualquier acción.": "我无法操作账户，也不能创建、发布、接受或支付任何内容。这一限制保护你的决定。我可以说明流程、帮助你比较条件，并指出你在亲自操作前需要检查的事项。",
    "No se activará la remuneración hasta que las reglas estén publicadas.": "相关规则公布前不会启用报酬。",
    "NO SE PUDO COMPROBAR": "无法完成检查",
    "No son el mismo documento. Confirmación, justificante, liquidación y factura cumplen funciones distintas. allwain publicará el recorrido fiscal antes de activar pagos reales.": "它们不是同一种文件。确认、凭证、结算单和发票具有不同作用。allwain 会在启用真实付款前公布完整税务流程。",
    "NO VENDEMOS TUS DATOS": "我们不出售你的数据",
    "No. allwain no vende datos personales ni integra seguimiento publicitario. Usa datos limitados para prestar, proteger y cumplir el servicio.": "不会。allwain 不出售个人数据，也不使用广告跟踪。它仅使用有限数据来提供、保护服务并履行相关义务。",
    "No. La primera propuesta no gana automáticamente. El comprador compara precio, condiciones y encaje, y decide.": "不会。第一个方案不会自动胜出。买家会比较价格、条件和匹配程度，再作决定。",
    "No. Publicar una petición y recibir propuestas no te obliga a aceptar, reservar ni pagar. Si ninguna encaja, no eliges ninguna.": "不会。发布需求并收到方案，不代表你必须接受、预订或付款。如果都不合适，可以一个都不选。",
    "No. Ser Conector no te convierte en repartidor. Recomendar y transportar son tareas distintas; una futura entrega solo se asumirá si encaja y la aceptas expresamente.": "不会。成为连接者并不意味着成为配送员。推荐和运输是两项不同的任务；未来只有在配送适合你且你明确接受时，才会由你承担。",
