    "Puedes explorar sin cuenta; identifícate para conservar el progreso.": "无需账户也可探索；登录后可以保存进度。",
    "Puedes ordenar las propuestas por precio, valoración o fecha y abrir cada una para revisar quién vende, el precio, la descripción y el plazo de entrega. allwain mostrará también cantidad, precio unitario, total y condiciones antes de la primera venta; comparar no te obliga a aceptar ninguna.": "你可以按价格、评分或日期排序方案，并打开每个方案查看卖家、价格、描述和交付期限。首次销售前，allwain 还会显示数量、单价、总价和条件；比较并不意味着必须接受任何方案。",
    "Puedes participar como Comprador, Vendedor o Conector. allwain nace en Foios como laboratorio de prueba: buscamos personas que recorran la web y la primera preventa de naranjas, encuentren fallos y nos cuenten qué mejorar.": "你可以作为买家、卖家或连接者参与。allwain 诞生于 Foios，并把这里作为测试实验室：我们希望有人体验网站和首次橙子预售，发现问题并告诉我们如何改进。",
    "Puedes participar como Comprador, Vendedor o Conector. El laboratorio de allwain nace en Foios: buscamos personas que recorran la web y la primera preventa de naranjas, encuentren fallos y nos cuenten qué mejorar.": "你可以作为买家、卖家或连接者参与。allwain 实验室诞生于 Foios：我们希望有人体验网站和首次橙子预售，发现问题并告诉我们如何改进。",
    "Puedes participar como Comprador, Vendedor o Conector. Las ocho pantallas y sus maquetas se exploran libremente. Para ser tester, responde la encuesta; después, la sala privada te guía para probar la app y reportar allí sus incidencias.": "你可以作为买家、卖家或连接者参与。八个页面及其原型均可自由探索。如需成为测试用户，请填写问卷；随后，私人测试空间会引导你测试应用并在其中报告问题。",
    "QR + red visible": "二维码 + 可见网络",
    "que resolver.": "解决的问题。",
