    "Responde una encuesta de menos de un minuto. Al identificarte, entrarás en la sala privada con una guía para probar la app y reportar incidencias.": "填写一份不到一分钟的问卷。登录后，你将进入私人空间，按照指南测试应用并报告问题。",
