    "Si aún no tienes cuenta, abrirás el registro. Si ya estás identificado, entrarás en el recorrido guiado existente.": "如果你还没有账户，将进入注册流程；如果已经登录，则进入现有的引导课程。",
    "Si un producto se vende aquí, no hace falta traerlo de otra parte del mundo.": "如果这里就有这种产品，就不必从世界另一端运来。",
    "Si un producto se vende aquí, no hace falta traerlo de otra parte del mundo. allwain quiere medir esa sostenibilidad real mostrando origen, ruta, recogida y entrega; la localidad del cartel solo se personaliza si das permiso al navegador y no se guarda.": "如果这里就有这种产品，就不必从世界另一端运来。allwain 希望通过展示产地、路线、取货和交付来衡量这种真正的可持续性；只有在你授权浏览器后，标牌中的地点才会个性化，而且不会被保存。",
    "Si ya respondiste la encuesta con esta cuenta, recuperaremos tu sala y tu progreso.": "如果你已使用此账户完成问卷，我们会恢复你的测试空间和进度。",
