    "SIN ANUNCIOS": "无广告",
    "Sin cuotas, niveles ni ingresos garantizados. Porcentajes, condiciones y fiscalidad se publicarán antes del primer pago.": "不收会费、不设等级，也不保证收入。首次付款前将公布比例、条件和税务说明。",
