    "Solo por operaciones válidas y terminadas, nunca por altas. Publicaremos importes, reglas y fiscalidad antes del primer pago.": "仅针对有效且已完成的交易，绝不按注册人数计酬。首次付款前，我们会公布金额、规则和税务说明。",
    "Solo por operaciones válidas y terminadas, nunca por altas. Se publicarán importes, reglas y fiscalidad antes del primer pago.": "只针对有效且已完成的交易，绝不按注册人数计算。金额、规则和税务处理会在首次付款前公布。",
    "Solo puedo responder sobre allwain: cómo funciona, sus roles, la prueba de Foios, privacidad, seguridad y fiscalidad.": "我只能回答与 allwain 相关的问题：其运作方式、角色、Foios 测试、隐私、安全和税务。",
    "Solo respondo sobre allwain: cómo funciona, sus tres papeles, la prueba de Foios, privacidad, seguridad y fiscalidad. Prueba con una pregunta concreta.": "我只回答与 allwain 相关的问题：运作方式、三种角色、Foios 测试、隐私、安全和税务。请尝试提出一个具体问题。",
    "Solo se afirmará para un lote cuando exista evidencia analítica suficiente.": "仅在具备充分检测证据时，才会对某一批次作出此声明。",
    "Solo se marca un paso cuando tú lo confirmas.": "只有经你确认后，步骤才会标记完成。",
