    "Soy la Guía IA pública. Explico allwain, la preventa próxima de naranjas de Foios y cómo participar. No veo datos privados ni hago operaciones.": "我是公共 AI 指南。我可以介绍 allwain、即将开启的 Foios 橙子预售以及参与方式。我看不到私人数据，也不会执行任何操作。",
