    "Abrir un enlace no marca nada automáticamente. En móvil, usa «Abrir la app»; en ordenador puedes usar la alternativa web. No confirmes pagos ni publiques ofertas reales durante esta primera revisión.": "لا يؤدي فتح الرابط إلى تسجيل أي خطوة تلقائيًا. على الهاتف استخدم «فتح التطبيق»، وعلى الكمبيوتر يمكنك استخدام بديل الويب. لا تؤكد مدفوعات ولا تنشر عروضًا حقيقية أثناء هذه المراجعة الأولى.",
    "Abrir un enlace no marca nada automáticamente. No confirmes pagos ni publiques ofertas reales durante esta primera revisión.": "لا يؤدي فتح الرابط إلى تسجيل أي خطوة تلقائيًا. لا تؤكد مدفوعات ولا تنشر عروضًا حقيقية أثناء هذه المراجعة الأولى.",
