    "Al entrar enviaremos tus respuestas automáticamente.": "سنرسل إجاباتك تلقائيًا عند الدخول.",
    "Al entrar recuperaremos de forma segura tu recorrido de prueba.": "عند تسجيل الدخول، سنستعيد مسار اختبارك بأمان.",
