    "allwain — Preventa próxima de naranjas de Foios": "allwain — بيع مسبق قريبًا لبرتقال Foios",
    "allwain crece": "ينمو allwain",
    "allwain empieza aquí como laboratorio real: un único producto, naranjas Navel Lane Late, y personas invitadas a probar, señalar fallos y opinar antes de la preventa.": "يبدأ allwain هنا كمختبر واقعي: منتج واحد، برتقال Navel Lane Late، وأشخاص مدعوون للتجربة وكشف المشكلات وإبداء الرأي قبل البيع المسبق.",
    "allwain no integra publicidad ni vende datos personales. Cada acción importante necesita confirmación y cada operación conserva un rastro comprensible.": "لا يدمج allwain إعلانات ولا يبيع البيانات الشخصية. كل إجراء مهم يحتاج إلى تأكيد، ولكل عملية سجل واضح.",
    "allwain no vende datos personales ni integra seguimiento publicitario. Esta Guía no entra en tu cuenta. La conexión usa HTTPS y las sesiones son revocables: son controles reales y evolutivos, no una promesa de invulnerabilidad.": "لا يبيع allwain البيانات الشخصية ولا يستخدم التتبع الإعلاني. لا يدخل هذا الدليل إلى حسابك. يستخدم الاتصال HTTPS ويمكن إلغاء الجلسات؛ هذه ضوابط فعلية ومتطورة وليست وعدًا بحصانة مطلقة.",
    "allwain solo mostrará este distintivo cuando la documentación del lote haya sido comprobada.": "لن تعرض allwain هذه الشارة إلا بعد التحقق من وثائق الدفعة.",
    "allwain solo mostrará este distintivo cuando la documentación del lote haya sido comprobada. No es un certificado oficial único ni afirma que un alimento importado legalmente incumpla las normas europeas.": "لن يعرض allwain هذه الشارة إلا بعد التحقق من وثائق الدفعة. ليست شهادة رسمية موحدة، ولا تعني أن الغذاء المستورد قانونيًا يخالف المعايير الأوروبية.",
    "allwain te dirá qué preparar": "سيخبرك allwain بما يجب تحضيره",
    "allwain tiene tres papeles: Comprador, que publica lo que necesita y elige; Vendedor, que responde con propuestas; y Conector, que acerca personas y negocios mediante su QR sin entrar en sus cuentas. Repartir es una función distinta y voluntaria.": "في allwain ثلاثة أدوار: المشتري ينشر حاجته ويختار؛ والبائع يرد بعروض؛ والموصّل يقرّب الأشخاص والمنشآت عبر QR دون دخول حساباتهم. التوصيل مهمة مختلفة واختيارية.",
    "allwain usa HTTPS, cabeceras de seguridad y sesiones revocables. Son controles reales y evolutivos, no una promesa de invulnerabilidad.": "تستخدم allwain بروتوكول HTTPS وترويسات أمان وجلسات قابلة للإلغاء. هذه ضوابط حقيقية تتطور باستمرار، وليست وعدًا بعدم التعرض لأي اختراق.",
