    "EJEMPLO": "مثال",
    "Ejemplo de comarca: más alcance exige más soporte y reglas claras; no implica ingresos garantizados.": "مثال لشبكة على مستوى المنطقة: يتطلب الانتشار الأوسع دعمًا أكبر وقواعد واضحة؛ ولا يعني دخلًا مضمونًا.",
    "Ejemplo de red de pueblo: se atribuye quién llegó contigo y qué operaciones completa, nunca simples altas.": "مثال لشبكة البلدة: تُنسب إليك هوية من انضم عن طريقك والعمليات التي أكملها، وليس مجرد التسجيلات.",
    "Ejemplo de red inicial: el beneficio solo se compartiría cuando existan operaciones válidas y terminadas.": "مثال لشبكة أولية: لن تُشارك المنفعة إلا عند وجود عمليات صالحة ومكتملة.",
    "Ejemplo visual: precios y respuestas no reales. Tú decides si publicas y cuál eliges.": "مثال بصري: الأسعار والردود غير حقيقية. أنت تقرر النشر والاختيار.",
    "El Conector acerca compradores y negocios a su red local": "يقرّب الموصّل المشترين والمنشآت إلى شبكته المحلية",
    "El Conector comparte su QR, acerca compradores y negocios y activa allwain en su zona. La red que incorpora queda vinculada a él; recomendar no le da acceso a cuentas ni decisiones.": "يشارك الموصّل رمز QR، ويقرّب المشترين والمنشآت، ويفعّل allwain في منطقته. ترتبط به الشبكة التي يضمها، لكن التوصية لا تمنحه الوصول إلى الحسابات أو القرارات.",
    "El Conector comparte su QR, acerca compradores y negocios y activa la red de allwain en su zona. La red que incorpora queda vinculada a él; recomendar no le da acceso a cuentas ni decisiones.": "يشارك الموصّل رمز QR، ويقرّب المشترين والمنشآت، ويفعّل شبكة allwain في منطقته. ترتبط به الشبكة التي يضمها، لكن التوصية لا تمنحه الوصول إلى الحسابات أو القرارات.",
    "El distintivo de allwain solo se mostrará cuando la documentación del lote haya sido comprobada.": "لن تظهر شارة allwain إلا بعد التحقق من وثائق الدفعة.",
    "El envío es automático y queda vinculado a tu cuenta.": "يتم الإرسال تلقائيًا ويرتبط بحسابك.",
    "El laboratorio de allwain empieza aquí: un único producto, naranjas Navel Lane Late, y personas invitadas a probar, señalar fallos y opinar antes de la preventa.": "يبدأ مختبر allwain هنا: منتج واحد، برتقال Navel Lane Late، وأشخاص مدعوون للتجربة والإبلاغ عن المشكلات وإبداء الرأي قبل البيع المسبق.",
    "EL MERCADO AL REVÉS": "السوق بالعكس",
    "El modelo prevé que el Conector participe en cada compra o venta válida y terminada de su red. No cobra por altas. Los pagos, porcentajes y reglas se publicarán antes de activarse.": "ينص النموذج على مشاركة الموصّل في كل شراء أو بيع صالح ومكتمل داخل شبكته. لا يتقاضى مقابل التسجيل. ستُنشر المدفوعات والنسب والقواعد قبل تفعيلها.",
    "El modelo que queremos poner a prueba": "النموذج الذي نريد اختباره",
    "El objetivo de más de 300 % se comprobará frente a la referencia de origen que quede documentada en la prueba. El 50 % toma como referencia aportada 2 €/kg frente al objetivo de 1 €/kg para el producto. No son resultados confirmados. Entrega, comisiones, impuestos, embalaje, mermas y ajustes irán aparte y serán visibles.": "سيُتحقق من هدف الزيادة التي تتجاوز 300% بمقارنته بسعر المنشأ الموثق في الاختبار. ويقارن هدف 50% السعر المرجعي المقدم، 2 €/kg، بسعر المنتج المستهدف، 1 €/kg. هذه ليست نتائج مؤكدة. وسيُعرض التوصيل والعمولات والضرائب والتعبئة والفاقد والتعديلات بشكل منفصل.",
    "El primer QR y la hora confirman que el producto ha salido del punto acordado.": "يؤكد أول رمز QR والوقت أن المنتج غادر النقطة المتفق عليها.",
    "El progreso se guarda en tu cuenta de allwain.": "يُحفظ تقدمك في حسابك على allwain.",
    "EL QR YA SE PUEDE COMPARTIR · LOS PAGOS AÚN NO": "يمكن مشاركة QR الآن · المدفوعات ليست مفعّلة بعد",
    "El recorrido que puede evitarse cuando ya existe producto local": "مسار يمكن تجنبه عند توفر منتج محلي",
    "el reparto remunerado se probará cuando estén cerradas sus condiciones, seguro y obligaciones fiscales.": "سيُختبر التوصيل المدفوع بعد اعتماد شروطه والتأمين والالتزامات الضريبية.",
    "El segundo QR confirma la recepción y permite cerrar la operación con un rastro comprensible.": "يؤكد رمز QR الثاني الاستلام ويتيح إغلاق العملية مع سجل واضح.",
    "El vendedor encuentra peticiones reales en vez de esperar solo ante un catálogo y decide a cuáles responder con una propuesta competitiva. Gana una oportunidad de venta, no una venta garantizada: el comprador compara y elige. En la prueba de naranjas, más de 300 % para quien cultiva es un objetivo por comprobar, no un resultado confirmado.": "يجد البائع طلبات حقيقية بدل الاكتفاء بالانتظار خلف كتالوج، ويقرر أيها يجيب عنه بعرض تنافسي. إنها فرصة بيع وليست عملية بيع مضمونة: يقارن المشتري ويختار. وفي اختبار البرتقال، تمثل زيادة تتجاوز 300% للمزارع هدفًا يجب التحقق منه، وليست نتيجة مؤكدة.",
    "El vendedor entra.": "يدخل البائع.",
    "El vendedor podrá elegir una petición y responder con una oferta o una negociación": "يمكن للبائع اختيار طلب والرد بعرض أو تفاوض",
    "El vendedor ve peticiones compatibles, elige cuáles le interesan y responde con una oferta o una negociación. El comprador conserva la decisión.": "يرى البائع الطلبات المناسبة، ويختار ما يهمه، ويرد بعرض أو تفاوض. ويبقى القرار للمشتري.",
    "El visor convierte la etiqueta en una petición editable. La revisas y, con un toque, preguntas a una gran comunidad. Después comparas las respuestas.": "يحوّل الماسح الملصق إلى طلب قابل للتعديل. تراجعه، ثم ترسله إلى مجتمع كبير بلمسة واحدة، وبعدها تقارن الردود.",
    "Elegir cómo participar": "اختر طريقة المشاركة",
    "Elige al menos una respuesta. Puedes dejar las demás en blanco.": "اختر إجابة واحدة على الأقل. يمكنك ترك البقية فارغة.",
    "Elige cómo participar": "اختر طريقة مشاركتك",
