    "Eliminar cuenta": "حذف الحساب",
    "Eliminar una cuenta": "حذف حساب",
    "Email": "البريد الإلكتروني",
    "Email o contraseña incorrectos, o acceso temporalmente no disponible.": "البريد الإلكتروني أو كلمة المرور غير صحيحة، أو الدخول غير متاح مؤقتًا.",
    "Email o contraseña incorrectos.": "البريد الإلكتروني أو كلمة المرور غير صحيحين.",
    "Empezar la encuesta": "بدء الاستبيان",
    "Empiezo": "أبدأ",
    "En esta Guía se procesa el texto que escribes y un historial breve para entender preguntas de seguimiento. No entra en tu cuenta ni consulta pedidos, pagos o mensajes privados; allwain no vende datos personales.": "يعالج هذا الدليل النص الذي تكتبه وسجلًا قصيرًا للمحادثة لفهم الأسئلة التابعة. لا يدخل حسابك ولا يطّلع على الطلبات أو المدفوعات أو الرسائل الخاصة؛ ولا يبيع allwain البيانات الشخصية.",
    "En este centro comercial no descubre productos: descubre peticiones y grupos de demanda. Elige cuáles puede atender y responde con una oferta más competitiva.": "في هذا المركز التجاري لا يجد البائع منتجات، بل طلبات ومجموعات طلب. يختار ما يمكنه تلبيته ويقدّم عرضًا أكثر تنافسية.",
