    "ENTRA": "يدخل",
    "Entra con la misma cuenta que usarás en la app. Tendrás una guía de acciones, progreso e incidencias sin abrir el correo.": "سجّل الدخول بالحساب نفسه الذي ستستخدمه في التطبيق. ستحصل على دليل إجراءات وتتبع للتقدم وإبلاغ عن المشكلات من دون فتح البريد الإلكتروني.",
    "Entra con tu cuenta de allwain para guardar el recorrido y enviar incidencias.": "سجّل الدخول بحسابك على allwain لحفظ المسار وإرسال البلاغات.",
    "Entra con tu cuenta, vuelve al inicio y comprueba que entiendes cómo cambiar de espacio.": "سجّل الدخول بحسابك، وعد إلى الصفحة الرئيسية، وتحقق من فهمك لطريقة الانتقال بين الأقسام.",
