    "ENVÍO PROTEGIDO": "إرسال محمي",
    "Es un objetivo de la prueba, todavía no un resultado.": "هذا هدف للاختبار، وليس نتيجة بعد.",
    "Escena fotográfica representativa de una persona compartiendo un QR con una comerciante y un vecino": "مشهد تمثيلي لشخص يشارك رمز QR مع تاجرة وأحد الجيران",
    "Escribe una pregunta…": "اكتب سؤالًا…",
    "Ese email ya tiene cuenta. Pulsa «Ya tengo cuenta».": "لهذا البريد حساب بالفعل. اختر «لدي حساب».",
    "Eso es sostenibilidad real.": "هذه هي الاستدامة الحقيقية.",
    "Español": "Español",
    "Esperando tu permiso. No guardaremos la ubicación.": "بانتظار إذنك. لن نحفظ الموقع.",
    "está agrupada.": "مجمّعًا.",
    "Estado de la sesión y configuración de la prueba": "حالة الجلسة وإعدادات الاختبار",
    "Estamos comprobando de forma segura si ya completaste la antesala.": "نتحقق بصورة آمنة مما إذا كنت قد أكملت الاستبيان التمهيدي.",
    "Estás interactuando con una IA. Tu pregunta y, cuando haga falta, una pregunta reciente de esta conversación pueden ser procesadas por OpenAI. No escribas nombres, direcciones, documentos, tarjetas ni datos de una operación.": "أنت تتفاعل مع ذكاء اصطناعي. قد تعالج OpenAI سؤالك، وعند الحاجة سؤالًا حديثًا من هذه المحادثة. لا تكتب أسماء أو عناوين أو وثائق أو بيانات بطاقات أو تفاصيل عملية.",
    "Este espacio no evalúa las maquetas de la web. Te acompaña en acciones concretas dentro de la app y reúne tu progreso e incidencias en una sola cuenta.": "لا يقيّم هذا القسم نماذج الموقع. بل يرافقك في إجراءات محددة داخل التطبيق، ويجمع تقدمك وبلاغاتك في حساب واحد.",
    "Este navegador no ofrece geolocalización. Mantenemos de Foios a Foios.": "هذا المتصفح لا يدعم تحديد الموقع. سنُبقي المسار من Foios إلى Foios.",
    "Estoy probando en": "أختبر على",
    "Explora cómo se comparte el beneficio.": "استكشف كيف تُشارك المنفعة.",
    "Explorar Conector": "استكشاف دور الموصّل",
    "FOIOS": "FOIOS",
    "Fotografías una etiqueta o explicas qué necesitas. allwain prepara un borrador para que lo revises; tú confirmas la petición, comparas respuestas y eliges.": "تصوّر ملصقًا أو تشرح ما تحتاجه. يُعد allwain مسودة تراجعها؛ ثم تؤكد الطلب وتقارن الردود وتختار.",
