    "Guardando tu confirmación…": "جارٍ حفظ تأكيدك…",
    "Guardando…": "جارٍ الحفظ…",
    "GUÍA DE ACCIONES": "دليل الإجراءات",
    "GUÍA DE ACCIONES EN LA APP": "دليل إجراءات التطبيق",
    "GUÍA IA PÚBLICA": "دليل ذكاء اصطناعي عام",
    "Guía IA pública de allwain": "دليل allwain العام بالذكاء الاصطناعي",
    "Guía no disponible": "الدليل غير متاح",
    "Hay tres papeles en allwain: Comprador, que publica lo que necesita y elige; Vendedor, que responde con propuestas; y Conector, que acerca personas y negocios mediante su QR sin entrar en sus cuentas. Repartir es una función distinta y voluntaria.": "في allwain ثلاثة أدوار: المشتري ينشر حاجته ويختار؛ والبائع يرد بعروض؛ والموصّل يقرّب الأشخاص والمنشآت عبر QR دون دخول حساباتهم. التوصيل مهمة مختلفة واختيارية.",
    "Haz crecer la red": "وسّع الشبكة",
    "Haz crecer una zona": "نمِّ منطقة",
    "Haz la acción en la app. Después confírmala aquí.": "نفّذ الإجراء في التطبيق، ثم أكّده هنا.",
    "Haz una foto.": "التقط صورة.",
