    "La contraseña debe tener al menos 12 caracteres.": "يجب ألا تقل كلمة المرور عن 12 حرفًا.",
    "La contraseña viaja cifrada y no se guarda en esta página.": "تُنقل كلمة المرور مشفرة ولا تُحفظ في هذه الصفحة.",
    "La demanda y el volumen deben encajar": "يجب أن يتوافق الطلب مع الحجم",
    "La demanda ya": "الطلب أصبح",
    "La encuesta es la antesala de esta academia. Después de enviarla con tu cuenta, volverás aquí automáticamente.": "الاستبيان هو الخطوة التمهيدية لدخول أكاديمية الاختبار. بعد إرساله بحسابك ستعود إلى هنا تلقائيًا.",
    "La encuesta solo se registra vinculada a una identidad allwain. Al entrar, se enviará automáticamente sin abrir tu correo.": "يُسجّل الاستبيان مرتبطًا بهوية allwain فقط. بعد الدخول سيُرسل تلقائيًا دون فتح بريدك.",
    "La encuesta y tu identidad abren esta sala.": "يفتح الاستبيان وهويتك هذه الغرفة.",
    "La entrega cierra la ruta.": "يُغلق التسليم المسار.",
    "La entrega puede remunerar a alguien cercano.": "قد يمنح التوصيل أجرًا لشخص قريب.",
    "La fiscalidad del Conector aún no está activada. Su participación se plantea solo sobre compras o ventas válidas y terminadas de su red, nunca por altas; porcentajes, impuestos, justificantes y liquidaciones se publicarán antes del primer pago.": "لم تُفعّل ضرائب الموصّل بعد. المشاركة مقررة فقط في مشتريات أو مبيعات شبكته الصالحة والمكتملة، وليس مقابل التسجيل. ستُنشر النسب والضرائب والإيصالات والتسويات قبل أول دفعة.",
    "La incidencia llega automáticamente al panel de soporte y queda vinculada a tu cuenta. No se abre el correo.": "يصل البلاغ تلقائيًا إلى لوحة الدعم ويرتبط بحسابك. لن يفتح تطبيق البريد.",
    "La misma identidad enlaza la encuesta, este recorrido y tus incidencias.": "تربط الهوية نفسها الاستبيان بهذا المسار وبلاغاتك.",
    "La persona que reparte ve distancia, importe y condiciones. Esta maqueta no inicia ninguna ruta.": "يرى من ينفّذ التوصيل المسافة والمبلغ والشروط. لا يبدأ هذا النموذج أي مسار.",
    "La presentación funciona sin JavaScript. Para usar la Guía pública necesitas activarlo.": "يعمل العرض دون JavaScript. لاستخدام الدليل العام، يجب تفعيله.",
    "LA PREVENTA AÚN NO HA EMPEZADO": "لم يبدأ البيع المسبق بعد",
    "La preventa aún no se ha abierto porque esta primera prueba debe cerrar condiciones de participación, entrega, trazabilidad y soporte. La web pública explica el modelo con maquetas libres; la prueba y sus incidencias se realizan en la app desde la sala privada. Cuando esos puntos estén verificados, se publicará una fecha.": "لم يُفتح البيع المسبق بعد لأن هذه التجربة الأولى ما زالت بحاجة إلى استكمال شروط المشاركة والتسليم والتتبّع والدعم. يشرح الموقع العام النموذج من خلال نماذج يمكن استكشافها بحرية؛ أما الاختبار وبلاغاته فتُجرى في التطبيق انطلاقًا من الغرفة الخاصة. سيُنشر موعد بعد التحقق من هذه النقاط.",
    "La preventa es próxima, pero todavía no hay una fecha pública confirmada. Empezará con naranjas Navel Lane Late de Foios a 1 €/kg como precio objetivo; antes se publicarán las condiciones de entrega y participación.": "البيع المسبق قريب، لكن لا يوجد موعد عام مؤكد بعد. سيبدأ ببرتقال Navel Lane Late من Foios بسعر مستهدف 1 €/kg؛ وستُنشر شروط التوصيل والمشاركة قبل ذلك.",
    "La preventa y la primera operación siguen pendientes.": "البيع المسبق وأول عملية لم يبدآ بعد.",
    "La primera prueba": "الاختبار الأول",
    "La prueba de las naranjas": "اختبار البرتقال",
    "La prueba empezará con un único producto: naranjas Navel Lane Late de Foios, de calidad, gran calibre y naranja intenso. Un euro por kilo es el objetivo del producto; la preventa y la primera venta siguen pendientes. Más de 300 % más para quien cultiva y 50 % menos para quien compra son objetivos comparados con las referencias aportadas, no resultados confirmados.": "سيبدأ الاختبار بمنتج واحد: برتقال Navel Lane Late عالي الجودة من Foios، كبير الحجم وبلون برتقالي قوي. يورو واحد للكيلوغرام هو سعر المنتج المستهدف؛ ولم يبدأ البيع المسبق أو أول بيع بعد. الزيادة التي تتجاوز 300% للمزارع والسعر الأقل بـ50% للمشتري هدفان مقارنة بالمراجع المقدمة، وليسا نتائج مؤكدة.",
    "La recogida deja una prueba verificable.": "يترك الاستلام دليلًا قابلًا للتحقق.",
    "La red de allwain crece": "تنمو شبكة allwain",
    "La ruta debe poder demostrarse de principio a fin, sin prometer resultados antes de probarla.": "يجب إثبات المسار من بدايته إلى نهايته، بلا وعود بنتائج قبل اختباره.",
    "La ruta une dos puntos cercanos.": "يربط المسار نقطتين متقاربتين.",
    "La sesión ha caducado. Identifícate de nuevo para continuar.": "انتهت صلاحية الجلسة. سجّل الدخول مجددًا للمتابعة.",
    "La sesión no se ha confirmado. Vuelve a intentarlo.": "لم تُؤكد الجلسة. حاول مجددًا.",
    "LABORATORIO DE PRUEBA": "مختبر الاختبار",
    "Las siete preguntas están juntas y son opcionales. Al enviar e identificarte, se abrirá la sala privada para probar la app.": "تظهر الأسئلة السبعة معًا وكلها اختيارية. بعد الإرسال وتسجيل الدخول ستُفتح الغرفة الخاصة لاختبار التطبيق.",
    "Las siete preguntas están juntas. Puedes saltarte las seis primeras; elige tu papel para personalizar la ruta privada.": "تظهر الأسئلة السبعة معًا. يمكنك تخطي الأسئلة الستة الأولى؛ اختر دورك لتخصيص المسار الخاص.",
