    "Los alimentos importados que se comercializan legalmente en la UE también deben respetar sus límites máximos de residuos. La diferencia que haremos visible es que algunos países terceros pueden autorizar durante el cultivo sustancias no aprobadas para uso agrícola dentro de la Unión Europea.": "يجب أيضًا أن تلتزم الأغذية المستوردة والمسوّقة قانونيًا في الاتحاد الأوروبي بحدوده القصوى للمتبقيات. والفرق الذي سنوضحه هو أن بعض الدول خارج الاتحاد قد تسمح أثناء الزراعة بمواد غير معتمدة للاستخدام الزراعي داخله.",
