    "No hemos podido enviar la incidencia. Inténtalo de nuevo.": "تعذر إرسال البلاغ. حاول مرة أخرى.",
    "No hemos podido enviar la incidencia. Revisa los campos e inténtalo de nuevo.": "لم نتمكن من إرسال البلاغ. راجع الحقول وحاول مجددًا.",
    "No hemos podido enviar tu opinión.": "تعذر إرسال رأيك.",
    "No hemos podido guardar este paso. Inténtalo de nuevo.": "لم نتمكن من حفظ هذه الخطوة. حاول مجددًا.",
    "No hemos podido guardar tu opinión. Inténtalo de nuevo.": "تعذر حفظ رأيك. حاول مجددًا.",
    "No hemos podido obtener la localidad. Mantenemos de Foios a Foios.": "تعذر تحديد البلدة. سنُبقي المسار من Foios إلى Foios.",
    "No mostramos email, domicilio ni documentos. Evita incluir datos personales en las incidencias.": "لا نعرض البريد الإلكتروني أو عنوان السكن أو الوثائق. تجنب إدراج بيانات شخصية في البلاغات.",
    "No puedo actuar en una cuenta ni crear, publicar, aceptar o pagar nada. Ese límite protege tu decisión. Sí puedo explicarte el recorrido, ayudarte a comparar condiciones y señalar qué debes revisar antes de que tú realices cualquier acción.": "لا يمكنني التصرف داخل حساب أو إنشاء شيء أو نشره أو قبوله أو دفع ثمنه. يحمي هذا الحد قرارك. يمكنني شرح المسار ومساعدتك على مقارنة الشروط وبيان ما ينبغي مراجعته قبل أن تنفذ أنت أي إجراء.",
    "No se activará la remuneración hasta que las reglas estén publicadas.": "لن يُفعّل المقابل المالي قبل نشر القواعد.",
    "NO SE PUDO COMPROBAR": "تعذر التحقق",
    "No son el mismo documento. Confirmación, justificante, liquidación y factura cumplen funciones distintas. allwain publicará el recorrido fiscal antes de activar pagos reales.": "ليست الوثائق نفسها. للتأكيد والإيصال والتسوية والفاتورة وظائف مختلفة. سينشر allwain المسار الضريبي قبل تفعيل المدفوعات الحقيقية.",
    "NO VENDEMOS TUS DATOS": "لا نبيع بياناتك",
    "No. allwain no vende datos personales ni integra seguimiento publicitario. Usa datos limitados para prestar, proteger y cumplir el servicio.": "لا. لا يبيع allwain البيانات الشخصية ولا يستخدم التتبع الإعلاني. يستخدم بيانات محدودة لتقديم الخدمة وحمايتها والامتثال للالتزامات.",
    "No. La primera propuesta no gana automáticamente. El comprador compara precio, condiciones y encaje, y decide.": "لا. العرض الأول لا يفوز تلقائيًا. يقارن المشتري السعر والشروط ومدى الملاءمة ثم يقرر.",
    "No. Publicar una petición y recibir propuestas no te obliga a aceptar, reservar ni pagar. Si ninguna encaja, no eliges ninguna.": "لا. نشر طلب وتلقي عروض لا يلزمك بالقبول أو الحجز أو الدفع. إذا لم يناسبك أي عرض فلا تختار شيئًا.",
    "No. Ser Conector no te convierte en repartidor. Recomendar y transportar son tareas distintas; una futura entrega solo se asumirá si encaja y la aceptas expresamente.": "لا. كونك موصّلًا لا يجعلك مندوب توصيل. التوصية والنقل مهمتان مختلفتان؛ ولن تتولى توصيلًا مستقبليًا إلا إذا ناسبك ووافقت عليه صراحة.",
    "Nombre": "الاسم",
