    "Puedes explorar sin cuenta; identifícate para conservar el progreso.": "يمكنك الاستكشاف بلا حساب؛ سجّل الدخول للاحتفاظ بتقدمك.",
    "Puedes ordenar las propuestas por precio, valoración o fecha y abrir cada una para revisar quién vende, el precio, la descripción y el plazo de entrega. allwain mostrará también cantidad, precio unitario, total y condiciones antes de la primera venta; comparar no te obliga a aceptar ninguna.": "يمكنك ترتيب العروض حسب السعر أو التقييم أو التاريخ، وفتح كل عرض لمراجعة البائع والسعر والوصف وموعد التسليم. وسيعرض allwain أيضًا الكمية وسعر الوحدة والإجمالي والشروط قبل أول بيع؛ والمقارنة لا تلزمك بقبول أي عرض.",
    "Puedes participar como Comprador, Vendedor o Conector. allwain nace en Foios como laboratorio de prueba: buscamos personas que recorran la web y la primera preventa de naranjas, encuentren fallos y nos cuenten qué mejorar.": "يمكنك المشاركة كمشترٍ أو بائع أو موصّل. يبدأ allwain في Foios كمختبر: نبحث عن أشخاص يجرّبون الموقع وأول بيع مسبق للبرتقال، ويكشفون المشكلات ويخبروننا بما نُحسّنه.",
    "Puedes participar como Comprador, Vendedor o Conector. El laboratorio de allwain nace en Foios: buscamos personas que recorran la web y la primera preventa de naranjas, encuentren fallos y nos cuenten qué mejorar.": "يمكنك المشاركة كمشترٍ أو بائع أو موصّل. وُلد مختبر allwain في Foios: نبحث عن أشخاص يجرّبون الموقع وأول بيع مسبق للبرتقال، ويكشفون المشكلات ويخبروننا بما نُحسّنه.",
    "Puedes participar como Comprador, Vendedor o Conector. Las ocho pantallas y sus maquetas se exploran libremente. Para ser tester, responde la encuesta; después, la sala privada te guía para probar la app y reportar allí sus incidencias.": "يمكنك المشاركة بصفتك مشتريًا أو بائعًا أو موصّلًا. ويمكن استكشاف الشاشات الثماني ونماذجها بحرية. لكي تصبح مختبِرًا، أجب عن الاستبيان؛ ثم سترشدك الغرفة الخاصة إلى اختبار التطبيق والإبلاغ عن مشكلاته هناك.",
