    "Ruta base: primero acceso y después los principales espacios de la app.": "المسار الأساسي: الدخول أولًا، ثم الأقسام الرئيسية في التطبيق.",
    "Ruta general: acceso, compra, venta, Conector y ayuda.": "المسار العام: الدخول والشراء والبيع والموصّل والمساعدة.",
