    "Se enviará al panel de soporte de allwain junto con esta versión de la web. No incluyas datos personales.": "سيُرسل إلى لوحة دعم allwain مع إصدار الموقع هذا. لا تدرج بيانات شخصية.",
    "Se muestra el trayecto local necesario, sin publicar el domicilio de ninguna persona.": "يُعرض المسار المحلي الضروري من دون نشر عنوان منزل أي شخص.",
