    "Sí": "نعم",
    "Si aún no tienes cuenta, abrirás el registro. Si ya estás identificado, entrarás en el recorrido guiado existente.": "إن لم يكن لديك حساب فستفتح صفحة التسجيل. وإن كنت مسجّلًا فستدخل المسار الإرشادي الحالي.",
    "Si un producto se vende aquí, no hace falta traerlo de otra parte del mundo.": "إذا كان المنتج يُباع هنا، فلا حاجة إلى جلبه من مكان آخر في العالم.",
    "Si un producto se vende aquí, no hace falta traerlo de otra parte del mundo. allwain quiere medir esa sostenibilidad real mostrando origen, ruta, recogida y entrega; la localidad del cartel solo se personaliza si das permiso al navegador y no se guarda.": "إذا كان المنتج يُباع هنا، فلا حاجة إلى جلبه من مكان آخر في العالم. يريد allwain قياس هذه الاستدامة الحقيقية بإظهار المنشأ والمسار والاستلام والتسليم؛ ولا تتغير البلدة على اللافتة إلا بإذن المتصفح، ولا تُحفظ.",
    "Si ya respondiste la encuesta con esta cuenta, recuperaremos tu sala y tu progreso.": "إذا كنت قد أجبت عن الاستبيان بهذا الحساب، فسنستعيد غرفة الاختبار وتقدمك.",
