    "Solo por operaciones válidas y terminadas, nunca por altas. Publicaremos importes, reglas y fiscalidad antes del primer pago.": "فقط للعمليات الصالحة والمكتملة، وليس للتسجيل. سننشر المبالغ والقواعد والضرائب قبل أول دفعة.",
    "Solo por operaciones válidas y terminadas, nunca por altas. Se publicarán importes, reglas y fiscalidad antes del primer pago.": "فقط عن العمليات الصالحة والمكتملة، وليس عن التسجيلات. ستُنشر المبالغ والقواعد والمعالجة الضريبية قبل أول دفعة.",
    "Solo puedo responder sobre allwain: cómo funciona, sus roles, la prueba de Foios, privacidad, seguridad y fiscalidad.": "لا يمكنني الإجابة إلا عن allwain: طريقة عمله، وأدواره، واختبار Foios، والخصوصية، والأمان، والضرائب.",
